// ИСПРАВЛЕННАЯ ФУНКЦИЯ: Преобразование недельных данных в дневные
function convertWeeklyToDaily() {
    const dailyData = [];
    const weeklyRows = [];

    // Сначала разделяем недельные и дневные данные
    allData.forEach(row => {
        const hasWeekField = row.hasOwnProperty('Неделя') || row.hasOwnProperty('﻿Неделя');
        const hasDateField = row.hasOwnProperty('Дата') && row.Дата && row.Дата.trim() !== '';
        
        if (hasWeekField && !hasDateField) {
            weeklyRows.push(row);
        } else if (hasDateField) {
            dailyData.push(row);
        }
    });
    
    console.log('Найдено недельных записей:', weeklyRows.length);
    console.log('Найдено дневных записей:', dailyData.length);
    
    // Обрабатываем недельные записи
    weeklyRows.forEach(row => {
        const weekStr = row['Неделя'] || row['﻿Неделя'];
        if (!weekStr) return;
        
        try {
            const parts = weekStr.split(' - ');
            if (parts.length !== 2) {
                console.warn('Неверный формат недели:', weekStr);
                return;
            }
            
            const startStr = parts[0].trim();
            const endStr = parts[1].trim();
            
            // Парсим даты (формат DD.MM.YYYY или DD.MM.YY)
            const parseDate = (dateStr) => {
                const [day, month, year] = dateStr.split('.');
                let fullYear = parseInt(year);
                if (fullYear < 100) fullYear += 2000;
                return new Date(fullYear, parseInt(month) - 1, parseInt(day));
            };
            
            const startDate = parseDate(startStr);
            const endDate = parseDate(endStr);
            
            if (isNaN(startDate) || isNaN(endDate)) {
                console.warn('Ошибка парсинга дат недели:', weekStr);
                return;
            }
            
            // Рассчитываем количество дней в неделе
            const daysCount = Math.floor((endDate - startDate) / (1000 * 60 * 60 * 24)) + 1;
            if (daysCount <= 0 || daysCount > 7) {
                console.warn('Некорректное количество дней в неделе:', daysCount, weekStr);
                return;
            }
            
            // Создаем дневные записи для каждого дня недели
            const currentDate = new Date(startDate);
            let dayIndex = 0;
            
            while (currentDate <= endDate && dayIndex < 7) {
                const dateStr = currentDate.toLocaleDateString('ru-RU');
                
                const dailyRow = {
                    Дата: dateStr,
                    Неделя: weekStr,
                    Объект: row.Объект || "",
                    Адрес: row.Адрес || ""
                };
                
                // Копируем все числовые поля, деля на количество дней
                for (const key in row) {
                    if (key !== 'Неделя' && key !== '﻿Неделя' && key !== 'Объект' && key !== 'Адрес') {
                        const value = row[key];
                        if (typeof value === 'number' && !isNaN(value)) {
                            // Для недельных данных - делим поровну на дни
                            dailyRow[key] = value / daysCount;
                        } else if (typeof value === 'string') {
                            dailyRow[key] = value;
                        } else if (typeof value === 'number') {
                            dailyRow[key] = 0;
                        }
                    }
                }
                
                dailyData.push(dailyRow);
                currentDate.setDate(currentDate.getDate() + 1);
                dayIndex++;
            }
        } catch (e) {
            console.error('Ошибка обработки недели:', weekStr, e);
            dailyData.push({ ...row, Дата: '' });
        }
    });
    
    // Сортируем по дате
    dailyData.sort((a, b) => {
        if (!a.Дата && !b.Дата) return 0;
        if (!a.Дата) return 1;
        if (!b.Дата) return -1;
        
        try {
            const dateA = new Date(a.Дата.split('.').reverse().join('-'));
            const dateB = new Date(b.Дата.split('.').reverse().join('-'));
            return dateA - dateB;
        } catch (e) {
            return 0;
        }
    });
    
    allData = dailyData;
    
    console.log('Всего дневных записей после конвертации:', allData.length);
    
    // Выводим пример данных для проверки
    if (allData.length > 0) {
        console.log('Пример дневной записи:', allData[0]);
        
        // Проверяем даты 9-10 мая
        const testDates = allData.filter(row => row.Дата === '09.05.2026' || row.Дата === '10.05.2026');
        console.log('Записей за 9-10 мая 2026:', testDates.length);
        if (testDates.length > 0) {
            let totalRevenue = 0;
            testDates.forEach(row => {
                const revenue = (row.Выручка || 0) + (row['Выручка Сайт'] || 0) + (row['Выручка Оборудование'] || 0);
                totalRevenue += revenue;
                console.log(`  ${row.Дата}: ${row.Объект} - ${row.Адрес} - Выручка: ${revenue}`);
            });
            console.log('Общая выручка за 9-10 мая:', totalRevenue);
        }
    }
}

// Функция для автоматической загрузки данных при старте
function loadEmbeddedData() {
  try {
    // Загружаем данные из embeddedData
    allData = embeddedData.mainData || [];
    otherExpensesData = embeddedData.expensesData || [];
    salaryOfficeData = embeddedData.salaryData || [];
    supportData = embeddedData.support || [];

    // ========== НОВОЕ: Исключаем "Франшиза роялти" ==========
    const beforeCount = allData.length;
    allData = allData.filter(row => {
      const object = String(row.Объект || '').trim();
      const address = String(row.Адрес || '').trim();
      // Исключаем записи с объектом "Франшиза роялти"
      if (object === 'Франшиза роялти') return false;
      // Исключаем записи с адресом "Франшиза роялти"
      if (address.toLowerCase().includes('франшиза роялти')) return false;
      return true;
    });
    console.log(`Исключено записей "Франшиза роялти": ${beforeCount - allData.length}`);

    // ПРЕОБРАЗУЕМ НЕДЕЛЬНЫЕ ДАННЫЕ В ДНЕВНЫЕ
    convertWeeklyToDaily();

    // ОБРАБОТКА ДАННЫХ ОПЛАТ
    otherExpensesData = otherExpensesData.map(expense => {
      const объект = getObjectByAddress(expense.мойка);
      const неделя = getWeekFromDate(expense.дата);
      return {
        ...expense,
        объект: объект,
        неделя: неделя
      };
    });

    // ОБРАБОТКА ЗАРПЛАТ
    salaryOfficeData = processSalaryData(salaryOfficeData);

    // Заполняем фильтры
    if (allData.length > 0) {
      populateFilters(allData);
      // Устанавливаем период по умолчанию
      setDefaultDateRange();
      applyFilters();
    }

  } catch (error) {
    console.error('Ошибка загрузки данных:', error);
  }
}

// НОВАЯ ФУНКЦИЯ: Обработка данных зарплат
function processSalaryData(salaryData) {
  if (!salaryData) return [];

  return salaryData.map(item => {
    // Исправляем "Nan" на пустую строку
    const employeeName = (item.сотрудник === "Nan" || item.сотрудник === "NaN") ? "" : item.сотрудник;
    const position = (item.должность === "Nan" || item.должность === "NaN") ? "" : item.должность;

    // Исправляем формат недели (добавляем 20 для годов)
    let weekStr = item.неделя || "Неизвестная неделя";
    weekStr = weekStr.replace(/(\d{2})\.(\d{2})\.(\d{2})/g, function (match, day, month, year) {
      const fullYear = year.length === 2 ? `20${year}` : year;
      return `${day}.${month}.${fullYear}`;
    });

    // Получаем месяц и год из недели
    const monthInfo = getPredominantMonthForWeek(weekStr);

    return {
      ...item,
      сотрудник: employeeName,
      должность: position,
      неделя: weekStr,
      месяц: monthInfo.month,
      год: monthInfo.year,
      дней_в_месяце: monthInfo.daysInMonth
    };
  });
}

// Вспомогательные функции
function getDaysInMonth(month, year) {
  const monthMap = {
    'Январь': 31,
    'Февраль': (year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)) ? 29 : 28,
    'Март': 31,
    'Апрель': 30,
    'Май': 31,
    'Июнь': 30,
    'Июль': 31,
    'Август': 31,
    'Сентябрь': 30,
    'Октябрь': 31,
    'Ноябрь': 30,
    'Декабрь': 31
  };
  return monthMap[month] || 30;
}

function getPredominantMonthForWeek(weekStr) {
  if (!weekStr) return { month: 'Октябрь', year: 2025, daysInMonth: 31 };
  try {
    const parts = weekStr.split(' - ');
    if (parts.length !== 2) return { month: 'Октябрь', year: 2025, daysInMonth: 31 };

    const startDate = new Date(parts[0].trim().split('.').reverse().join('-'));
    const endDate = new Date(parts[1].trim().split('.').reverse().join('-'));

    const monthDays = {};
    let currentDate = new Date(startDate);

    while (currentDate <= endDate) {
      const month = currentDate.toLocaleString('ru-RU', { month: 'long' });
      const capitalizedMonth = month.charAt(0).toUpperCase() + month.slice(1);
      const year = currentDate.getFullYear();
      const key = `${capitalizedMonth}_${year}`;
      monthDays[key] = (monthDays[key] || 0) + 1;
      currentDate.setDate(currentDate.getDate() + 1);
    }

    let maxDays = 0;
    let predominantMonthKey = '';
    for (const [key, days] of Object.entries(monthDays)) {
      if (days > maxDays) {
        maxDays = days;
        predominantMonthKey = key;
      }
    }

    if (predominantMonthKey) {
      const [month, year] = predominantMonthKey.split('_');
      const daysInMonth = getDaysInMonth(month, parseInt(year));
      return {
        month: month,
        year: parseInt(year),
        daysInMonth: daysInMonth,
        daysInWeek: maxDays
      };
    }
  } catch (e) {
    console.error('Ошибка определения месяца для недели:', weekStr, e);
  }
  return { month: 'Октябрь', year: 2025, daysInMonth: 31 };
}

function calculateSalaryForPeriod() {
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;
  if (!dateFrom || !dateTo) return 0;

  // Парсим даты из формата YYYY-MM-DD
  const fromDate = parseDateFromInput(dateFrom);
  const toDate = parseDateFromInput(dateTo);

  if (!fromDate || !toDate) return 0;

  // Определяем вчерашний день (начало дня)
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  yesterday.setHours(0, 0, 0, 0);

  // Ограничиваем конечную дату началом вчерашнего дня
  const maxAllowedDate = toDate > yesterday ? yesterday : toDate;

  // Проверяем, что начальная дата не позже конечной
  if (fromDate > maxAllowedDate) return 0;

  let totalSalaryExpense = 0;
  let processedWeeks = new Set();
  const weeklyData = {};

  salaryOfficeData.forEach(item => {
    if (!item.неделя) return;
    if (!weeklyData[item.неделя]) {
      weeklyData[item.неделя] = {
        сотрудники: [],
        месяц: item.месяц,
        год: item.год,
        дней_в_месяце: item.дней_в_месяце
      };
    }
    weeklyData[item.неделя].сотрудники.push(item);
  });

  for (const [weekStr, weekData] of Object.entries(weeklyData)) {
    try {
      const weekParts = weekStr.split(' - ');
      if (weekParts.length !== 2) continue;

      // Парсим даты недели (формат DD.MM.YY)
      const weekStart = parseWeekDate(weekParts[0].trim());
      const weekEnd = parseWeekDate(weekParts[1].trim());

      if (!weekStart || !weekEnd) continue;

      const weekInPeriod = (weekStart >= fromDate && weekStart <= maxAllowedDate) ||
        (weekEnd >= fromDate && weekEnd <= maxAllowedDate) ||
        (weekStart <= fromDate && weekEnd >= fromDate);

      if (weekInPeriod) {
        processedWeeks.add(weekStr);
        const weekStartInPeriod = weekStart < fromDate ? fromDate : weekStart;
        const weekEndInPeriod = weekEnd > maxAllowedDate ? maxAllowedDate : weekEnd;
        const weekDaysInPeriod = Math.ceil((weekEndInPeriod - weekStartInPeriod) / (1000 * 60 * 60 * 24)) + 1;

        if (weekDaysInPeriod <= 0) continue;

        weekData.сотрудники.forEach(item => {
          const totalAmount = item.исходные_данные?.итого || 0;
          const officeSalary = item.исходные_данные?.оф_зп || 0;
          const coefficient = item.исходные_данные?.коэффициент || 0;
          const daysInMonth = item.дней_в_месяце || weekData.дней_в_месяце || 30;
          const dailySalary = -((totalAmount + (officeSalary * coefficient)) / daysInMonth);
          const salaryForWeekDays = dailySalary * weekDaysInPeriod;
          totalSalaryExpense += salaryForWeekDays;
        });
      }
    } catch (e) {
      console.error('Ошибка обработки недели:', weekStr, e);
    }
  }

  return totalSalaryExpense;
}

// Вспомогательные функции для парсинга дат
function parseDateFromInput(dateStr) {
  if (!dateStr) return null;
  try {
    // Формат YYYY-MM-DD
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      const year = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1; // Месяцы 0-11 в JS
      const day = parseInt(parts[2], 10);
      return new Date(year, month, day, 0, 0, 0, 0);
    }
  } catch (e) {
    console.error('Ошибка парсинга даты из input:', dateStr, e);
  }
  return null;
}

function parseWeekDate(dateStr) {
  if (!dateStr) return null;
  try {
    // Формат DD.MM.YY или DD.MM.YYYY
    const parts = dateStr.split('.');
    if (parts.length === 3) {
      const day = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1;
      let year = parseInt(parts[2], 10);

      // Преобразуем двухзначный год в четырехзначный
      if (year < 100) {
        year = year + 2000; // Предполагаем 21 век
      }

      return new Date(year, month, day, 0, 0, 0, 0);
    }
  } catch (e) {
    console.error('Ошибка парсинга даты недели:', dateStr, e);
  }
  return null;
}

function getGeneralExpenseForDateRange() {
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;
  if (!dateFrom || !dateTo) return 0;

  const fromDate = new Date(dateFrom);
  const toDate = new Date(dateTo);

  const generalExpenses = otherExpensesData.filter(expense => {
    if (expense.мойка !== "Общий расход") return false;
    if (expense.команда && expense.команда.trim() !== '') return false;
    const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
    return expenseDate >= fromDate && expenseDate <= toDate;
  });

  return generalExpenses.reduce((sum, expense) => sum + expense.сумма, 0);
}

function getIndivisibleExpenseForDateRange(selectedObject, selectedAddresses) {
  if (!allData.length && !otherExpensesData.length) return 0;

  const isDrilldownMode = (!selectedObject || selectedObject === 'all_retail') &&
    (!selectedAddresses || selectedAddresses.length === 0);

  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;

  if (isDrilldownMode) {
    const indivisibleExpenses = otherExpensesData.filter(expense => {
      const isIndivisible = expense.мойка === "Общий расход" &&
        expense.команда &&
        String(expense.команда).toLowerCase() === 'розница';
      if (!isIndivisible) return false;
      if (dateFrom && dateTo) {
        const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        if (expenseDate < fromDate || expenseDate > toDate) return false;
      }
      return true;
    });
    return indivisibleExpenses.reduce((sum, expense) => sum + expense.сумма, 0);
  } else {
    let totalIndivisible = 0;
    let filteredData = allData;

    if (dateFrom && dateTo) {
      filteredData = allData.filter(row => {
        const rowDateStr = row.Дата;
        if (!rowDateStr) return true;
        try {
          const rowDate = new Date(rowDateStr.split('.').reverse().join('-'));
          const fromDate = new Date(dateFrom);
          const toDate = new Date(dateTo);
          return rowDate >= fromDate && rowDate <= toDate;
        } catch (e) {
          return true;
        }
      });
    }

    filteredData = filteredData.filter(row => {
      const rowObject = row.Объект;
      const rowAddress = row.Адрес;

      if (selectedObject) {
        if (selectedObject === 'all_retail') {
          if (!retailObjects.includes(rowObject)) return false;
        } else if (rowObject !== selectedObject) {
          return false;
        }
      }

      if (selectedAddresses && selectedAddresses.length > 0) {
        const rowStandardizedAddress = standardizeAddress(row.Адрес);
        let addressMatches = false;

        for (const selectedAddr of selectedAddresses) {
          const selectedStandardizedAddr = standardizeAddress(selectedAddr);
          if (rowStandardizedAddress === selectedStandardizedAddr) {
            addressMatches = true;
            break;
          }
        }

        if (!addressMatches) return false;
      }

      return true;
    });

    filteredData.forEach(row => {
      for (const key in row) {
        if (key.toLowerCase().includes('неделимый') || key === 'Неделимый расход') {
          totalIndivisible += parseFloat(row[key]) || 0;
          break;
        }
      }
    });

    return totalIndivisible;
  }
}

function getFilteredIndivisibleExpenses() {
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();
  const isDrilldownMode = (!selectedObject || selectedObject === 'all_retail') &&
    (!selectedAddresses || selectedAddresses.length === 0);

  if (!isDrilldownMode) return [];

  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;

  return otherExpensesData.filter(expense => {
    const isIndivisible = expense.мойка === "Общий расход" &&
      expense.команда &&
      String(expense.команда).toLowerCase() === 'розница';
    if (!isIndivisible) return false;
    if (dateFrom && dateTo) {
      const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
      const fromDate = new Date(dateFrom);
      const toDate = new Date(dateTo);
      if (expenseDate < fromDate || expenseDate > toDate) return false;
    }
    return true;
  });
}

// ИСПРАВЛЕННАЯ ФУНКЦИЯ getFilteredGeneralExpenseExpenses() - исключаем Инвестиционный расход с 01.04.2026
function getFilteredGeneralExpenseExpenses() {
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;
  
  // Дата начала исключения строительства из общего расхода
  const constructionExcludeStartDate = new Date('2026-04-01');

  return otherExpensesData.filter(expense => {
    // Базовые условия: мойка = "Общий расход" и нет команды
    if (expense.мойка !== "Общий расход") return false;
    if (expense.команда && expense.команда.trim() !== '') return false;
    
    // Исключаем Инвестиционный расход начиная с 01.04.2026
    if (expense.статья === "Инвестиционный расход нового объекта") {
      try {
        const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
        if (expenseDate >= constructionExcludeStartDate) {
          return false; // Исключаем из общего расхода
        }
      } catch (e) {
        console.error('Ошибка обработки даты строительства:', expense.дата, e);
      }
    }

    // Фильтрация по дате (основной период)
    if (dateFrom && dateTo) {
      try {
        const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        if (expenseDate < fromDate || expenseDate > toDate) return false;
      } catch (e) {
        console.error('Ошибка обработки даты:', expense.дата, e);
        return false;
      }
    }

    // Фильтрация по объекту (если выбран)
    if (selectedObject) {
      const expenseObject = getObjectByAddress(expense.мойка);

      if (selectedObject === 'all_retail') {
        if (!retailObjects.includes(expenseObject)) {
          return false;
        }
      } else if (expenseObject !== selectedObject) {
        return false;
      }
    }

    return true;
  });
}

// Функция для получения расходов на Инвестиционный расход
function getFilteredConstructionExpenses() {
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;

  // Проверяем, что находимся в режиме "Все объекты + Все адреса"
  const isAllObjectsAllAddresses = (!selectedObject || selectedObject === '') &&
    (!selectedAddresses || selectedAddresses.length === 0);

  if (!isAllObjectsAllAddresses) return [];

  // Дата начала учета строительства
  const constructionStartDate = new Date('2026-04-02');

  return otherExpensesData.filter(expense => {
    // Фильтруем по статье "Инвестиционный расход нового объекта"
    if (expense.статья !== "Инвестиционный расход нового объекта") return false;

    // Фильтруем по дате (если выбран период)
    if (dateFrom && dateTo) {
      try {
        const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);

        // Проверяем, что дата в периоде и не раньше 01.04.2026
        if (expenseDate < fromDate || expenseDate > toDate || expenseDate < constructionStartDate) {
          return false;
        }
      } catch (e) {
        console.error('Ошибка обработки даты строительства:', expense.дата, e);
        return false;
      }
    } else {
      // Если период не выбран, проверяем только дату начала
      try {
        const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
        if (expenseDate < constructionStartDate) return false;
      } catch (e) {
        return false;
      }
    }

    return true;
  });
}

// Функция для получения суммы расходов на Инвестиционный расход за период
function getConstructionExpenseForDateRange() {
  const expenses = getFilteredConstructionExpenses();
  return expenses.reduce((sum, expense) => sum + expense.сумма, 0);
}

// ИСПРАВЛЕННАЯ ФУНКЦИЯ: getFilteredOtherExpenses() - с поддержкой команд
function getFilteredOtherExpenses() {
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;

  console.log('=== ФИЛЬТРАЦИЯ "ПРОЧИХ" РАСХОДОВ ===');
  console.log('Период:', dateFrom, '-', dateTo);
  console.log('Объект:', selectedObject);
  console.log('Адреса:', selectedAddresses);

  // Проверяем, есть ли в отфильтрованных данных старые записи (с неделей)
  let filteredData = allData;

  if (dateFrom && dateTo) {
    filteredData = filteredData.filter(row => {
      if (row.Дата) {
        try {
          const rowDate = new Date(row.Дата.split('.').reverse().join('-'));
          const fromDate = new Date(dateFrom);
          const toDate = new Date(dateTo);
          return rowDate >= fromDate && rowDate <= toDate;
        } catch (e) {
          console.error('Ошибка обработки даты:', row.Дата, e);
          return false;
        }
      } else if (row.Неделя || row['﻿Неделя']) {
        try {
          const weekStr = row.Неделя || row['﻿Неделя'];
          const [startStr] = weekStr.split(' - ');
          const weekStart = new Date(startStr.trim().split('.').reverse().join('-'));
          const fromDate = new Date(dateFrom);
          const toDate = new Date(dateTo);
          return weekStart >= fromDate && weekStart <= toDate;
        } catch (e) {
          console.error('Ошибка обработки недели:', weekStr, e);
          return false;
        }
      }
      return false;
    });
  }

  // Фильтрация по объекту
  if (selectedObject) {
    if (selectedObject === 'all_retail') {
      filteredData = filteredData.filter(row => retailObjects.includes(row.Объект));
    } else {
      filteredData = filteredData.filter(row => row.Объект === selectedObject);
    }
  }

  // Фильтрация по адресам
  if (selectedAddresses && selectedAddresses.length > 0) {
    filteredData = filteredData.filter(row => {
      const rowAddress = String(row.Адрес || '').trim();
      if (!rowAddress) return false;

      const rowStandardizedAddress = standardizeAddress(rowAddress);

      for (const selectedAddr of selectedAddresses) {
        const selectedStandardizedAddr = standardizeAddress(selectedAddr);

        if (rowAddress === selectedAddr) return true;
        if (rowStandardizedAddress === selectedStandardizedAddr) return true;
        if (rowAddress.toLowerCase() === selectedAddr.toLowerCase()) return true;
        if (rowAddress.includes(selectedAddr) || selectedAddr.includes(rowAddress)) return true;
      }

      return false;
    });
  }

  console.log('Отфильтровано записей из mainData:', filteredData.length);

  // Определяем, есть ли старые данные (с неделей)
  const hasOldData = filteredData.some(row => row.Неделя || row['﻿Неделя']);
  const hasNewData = filteredData.some(row => row.Дата && !row.Неделя && !row['﻿Неделя']);

  console.log('Есть старые данные (с неделей):', hasOldData);
  console.log('Есть новые данные (с датой):', hasNewData);

  // ЕСЛИ ЕСТЬ СТАРЫЕ ДАННЫЕ - берем "Прочие" из них
  if (hasOldData && !hasNewData) {
    console.log('Используем старые данные для "Прочие"');

    // Суммируем "Прочие" из старых данных
    const oldDataProchie = filteredData.reduce((sum, row) => {
      const prochieValue = row['Прочие'] || 0;
      console.log(`Старые данные: Объект=${row.Объект}, Адрес=${row.Адрес}, Прочие=${prochieValue}`);
      return sum + prochieValue;
    }, 0);

    console.log('Итого "Прочие" из старых данных:', oldDataProchie);

    // Возвращаем массив с одной записью для совместимости с интерфейсом
    return [{
      сумма: oldDataProchie,
      статья: 'Прочие (из недельных данных)',
      наименование: 'Сумма из недельных отчетов',
      мойка: 'Старые данные',
      команда: '',
      дата: dateFrom && dateTo ? `${dateFrom} - ${dateTo}` : 'Период'
    }];
  }

  // ЕСЛИ ЕСТЬ ТОЛЬКО НОВЫЕ ДАННЫЕ - используем дриллдаун
  if (hasNewData && !hasOldData) {
    console.log('Используем новые данные (дриллдаун) для "Прочие"');
    return getOtherExpensesDrilldown(selectedObject, selectedAddresses, dateFrom, dateTo);
  }

  // ЕСЛИ ЕСТЬ И ТЕ, И ДРУГИЕ - комбинируем
  if (hasOldData && hasNewData) {
    console.log('Комбинируем старые и новые данные');

    // Старые данные
    const oldDataProchie = filteredData
      .filter(row => row.Неделя || row['﻿Неделя'])
      .reduce((sum, row) => sum + (row['Прочие'] || 0), 0);

    // Новые данные через дриллдаун
    const newDataExpenses = getOtherExpensesDrilldown(selectedObject, selectedAddresses, dateFrom, dateTo);
    const newDataProchie = newDataExpenses.reduce((sum, item) => sum + item.сумма, 0);

    console.log('Старые данные Прочие:', oldDataProchie);
    console.log('Новые данные Прочие:', newDataProchie);
    console.log('Всего Прочие:', oldDataProchie + newDataProchie);

    // Возвращаем объединенный результат
    const combined = [
      {
        сумма: oldDataProchie,
        статья: 'Прочие (недельные отчеты)',
        наименование: 'Сумма из недельных данных',
        мойка: 'Старые данные',
        команда: '',
        дата: dateFrom && dateTo ? `${dateFrom} - ${dateTo}` : 'Период'
      },
      ...newDataExpenses
    ];

    return combined;
  }

  // ЕСЛИ НЕТ ДАННЫХ В mainData, НО ПРИ ЭТОМ ВЫБРАН ОБЪЕКТ КОМАНДЫ
  // Нужно проверить otherExpensesData напрямую
  if (selectedObject && !hasOldData && !hasNewData) {
    console.log('Нет данных в mainData, проверяем otherExpensesData для объекта команды:', selectedObject);
    
    // Проверяем, является ли выбранный объект командой
    const isTeamObject = [
      "Команда автономности",
      "Команда распространения (монтажи)",
      "Команда маркетинга",
      "Команда качество",
      "Команда заботы",
      "Команда закупок, снабжения и логистики",
      "Команда HR и КДП",
      "Команда юристов",
      "Команда бухгалтерии",
      "Команда финансов"
    ].includes(selectedObject);
    
    if (isTeamObject) {
      console.log('Выбран объект команды, идем в дриллдаун');
      return getOtherExpensesDrilldown(selectedObject, selectedAddresses, dateFrom, dateTo);
    }
  }

  console.log('Нет данных для "Прочие"');
  return [];
}

function getAdjustedGeneralExpenseForDateRange() {
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;
  if (!dateFrom || !dateTo) return 0;

  const fromDate = new Date(dateFrom);
  const toDate = new Date(dateTo);

  let totalExpense = 0;
  let totalOutgoingVat = 0;

  otherExpensesData.forEach(expense => {
    // Фильтруем Общий расход (без команды)
    if (expense.мойка !== "Общий расход") return;
    if (expense.команда && expense.команда.trim() !== '') return;
    
    // ========== ДОБАВИТЬ ИСКЛЮЧЕНИЕ СТРОИТЕЛЬСТВА ==========
    if (expense.статья === "Инвестиционный расход нового объекта") return;
    // ======================================================
    
    const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
    if (expenseDate < fromDate || expenseDate > toDate) return;

    totalExpense += expense.сумма;
    totalOutgoingVat += expense.ндс_исходящий || 0;
  });

  return totalExpense + totalOutgoingVat;
}

// Функция для получения скорректированного расхода на Инвестиционный расход (без исходящего НДС)
function getAdjustedConstructionExpenseForDateRange() {
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;
  if (!dateFrom || !dateTo) return 0;

  const fromDate = new Date(dateFrom);
  const toDate = new Date(dateTo);
  const constructionStartDate = new Date('2026-04-02');

  let totalExpense = 0;
  let totalOutgoingVat = 0;

  otherExpensesData.forEach(expense => {
    // Фильтруем по статье Инвестиционный расход
    if (expense.статья !== "Инвестиционный расход нового объекта") return;

    // Фильтруем по дате
    const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
    if (expenseDate < fromDate || expenseDate > toDate) return;
    if (expenseDate < constructionStartDate) return;

    // Суммируем расход и исходящий НДС
    totalExpense += expense.сумма;
    totalOutgoingVat += expense.ндс_исходящий || 0;
  });

  // Возвращаем расход минус исходящий НДС
  // (например: -5169.68 + 932.24 = -4237.44)
  return totalExpense + totalOutgoingVat;
}

// Функция для расчета налога на прибыль (25% от скорректированной базы)
function calculateProfitTax(adjustedGeneralExpense, salaryOffice, adjustedConstruction) {
  // Налоговая база = Общий расход (скорректированный) + З/п офис + Инвестиционный расход (скорректированное)
  const taxBase = adjustedGeneralExpense + salaryOffice + adjustedConstruction;

  // Налог = 25% от базы (но только если база отрицательная, иначе налог 0)
  // В вашем примере: (-980000 - 300000 - 4237.44) * 0.25 = -321059.36
  // Отрицательный налог означает, что компания получает возврат из бюджета
  const taxRate = 0.25;
  const tax = taxBase * taxRate;

  console.log('=== РАСЧЕТ НАЛОГА ===');
  console.log('Скорректированный Общий расход:', formatCurrency(adjustedGeneralExpense));
  console.log('З/п офис:', formatCurrency(salaryOffice));
  console.log('Скорректированное Инвестиционный расход:', formatCurrency(adjustedConstruction));
  console.log('Налоговая база:', formatCurrency(taxBase));
  console.log('Налог (25%):', formatCurrency(tax));

  return tax;
}

// Функция для расчета операционной прибыли в режиме "Все объекты + Все адреса"
function calculateAdjustedOperatingProfit(regularRevenue, bonusRevenue, regularExpenses, indivisibleExpense, otherExpenses) {
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();

  // Проверяем режим "Все объекты + Все адреса"
  const isAllObjectsAllAddresses = (!selectedObject || selectedObject === '') &&
    (!selectedAddresses || selectedAddresses.length === 0);

  if (!isAllObjectsAllAddresses) {
    // Если не режим "Все объекты + Все адреса", возвращаем стандартную прибыль
    return regularRevenue + bonusRevenue +
      regularExpenses +
      indivisibleExpense +
      otherExpenses;
  }

  // Для режима "Все объекты + Все адреса" делаем специальный расчет

  // 1. Получаем скорректированные расходы
  const adjustedGeneralExpense = getAdjustedGeneralExpenseForDateRange();
  const adjustedConstruction = getAdjustedConstructionExpenseForDateRange();
  const salaryOffice = calculateSalaryForPeriod();

  // 2. Собираем все остальные расходы (кроме Общего расхода, З/п офис и Строительства)
  // Они уже должны быть учтены в regularExpenses, но нужно убедиться, что Общий расход и Инвестиционный расход исключены
  // Для этого пересчитаем все расходы, исключая те, что мы обрабатываем отдельно

  // Получаем оригинальные значения
  const originalGeneralExpense = getGeneralExpenseForDateRange();
  const originalConstruction = getConstructionExpenseForDateRange();

  // Остальные расходы = все регулярные расходы минус Общий расход минус Инвестиционный расход
  const otherRegularExpenses = regularExpenses - originalGeneralExpense - originalConstruction;

  // 3. Рассчитываем налог на прибыль
  const profitTax = calculateProfitTax(adjustedGeneralExpense, salaryOffice, adjustedConstruction);

  // 4. Чистая прибыль = Выручка - (все остальные расходы) - (скорректированный Общий расход) - 
  //    (скорректированное Инвестиционный расход) - (З/п офис) - (Налог)
  //    НО: поскольку Общий расход и Инвестиционный расход уже вычтены из regularExpenses, 
  //    мы должны заменить их на скорректированные версии

  const operatingProfit = (regularRevenue + bonusRevenue) +
    otherRegularExpenses +
    adjustedGeneralExpense +
    salaryOffice +
    adjustedConstruction +
    indivisibleExpense +
    profitTax;

  console.log('=== Чистая прибыль (СКОРРЕКТИРОВАННАЯ) ===');
  console.log('Выручка (основная):', formatCurrency(regularRevenue));
  console.log('Выручка (бонус):', formatCurrency(bonusRevenue));
  console.log('Остальные расходы:', formatCurrency(otherRegularExpenses));
  console.log('Неделимый расход:', formatCurrency(indivisibleExpense));
  console.log('Скорректированный Общий расход:', formatCurrency(adjustedGeneralExpense));
  console.log('З/п офис:', formatCurrency(salaryOffice));
  console.log('Скорректированное Инвестиционный расход:', formatCurrency(adjustedConstruction));
  console.log('Налог на прибыль:', formatCurrency(profitTax));
  console.log('Итоговая Чистая прибыль:', formatCurrency(operatingProfit));

  return operatingProfit;
}

// НОВАЯ ФУНКЦИЯ: Дриллдаун для новых данных
function getOtherExpensesDrilldown(selectedObject, selectedAddresses, dateFrom, dateTo) {
  console.log('=== ДРИЛЛДАУН ДЛЯ НОВЫХ ДАННЫХ ===');

  // Дата начала учета строительства как отдельной категории
  const constructionStartDate = new Date('2026-04-02');

  return otherExpensesData.filter(expense => {
    // 1. Проверяем, относится ли это к "Неделимому расходу"
    const isIndivisible = expense.мойка === "Общий расход" &&
      expense.команда &&
      String(expense.команда).toLowerCase() === 'розница';

    // 2. Проверяем, относится ли это к "Общему расходу"
    const isGeneralExpense = expense.мойка === "Общий расход" &&
      (!expense.команда || expense.команда.trim() === '');

    // 3. Проверяем, является ли это расходами на Инвестиционный расход (с 01.04.2026)
    let isConstruction = false;

    if (expense.статья === "Инвестиционный расход нового объекта") {
      try {
        const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
        if (expenseDate >= constructionStartDate) {
          isConstruction = true;
        }
      } catch (e) {
        console.error('Ошибка обработки даты строительства в дриллдауне:', expense.дата, e);
      }
    }

    // Если это "Неделимый", "Общий расход" или "Инвестиционный расход" (с 01.04.2026) - исключаем из "Прочих"
    if (isIndivisible || isGeneralExpense || isConstruction) {
      return false;
    }

    // Фильтрация по дате
    if (dateFrom && dateTo) {
      try {
        const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        if (expenseDate < fromDate || expenseDate > toDate) {
          return false;
        }
      } catch (e) {
        console.error('Ошибка обработки даты:', expense.дата, e);
        return false;
      }
    }

    // ========== ФИЛЬТРАЦИЯ ПО ОБЪЕКТУ - ИСПРАВЛЕННАЯ ВЕРСИЯ ==========
    if (selectedObject) {
      if (selectedObject === 'all_retail') {
        // Для розницы: только розничные объекты
        if (!retailObjects.includes(expense.объект)) {
          return false;
        }
      } else {
        // Для конкретного объекта:
        // Сравниваем с expense.мойка (а не с expense.объект), 
        // потому что у команд мойка = название команды
        if (expense.мойка !== selectedObject) {
          return false;
        }
      }
    }

    // ФИЛЬТРАЦИЯ ПО АДРЕСАМ
    if (selectedAddresses && selectedAddresses.length > 0) {
      // Для "Прочих" учитываем только записи с конкретной мойкой
      if (!expense.мойка || expense.мойка === "Общий расход") {
        // Если у записи нет мойки или это "Общий расход" - исключаем
        return false;
      }

      // Стандартизируем адрес для сравнения
      const expenseStandardizedAddress = standardizeAddress(expense.мойка);

      let addressMatches = false;
      for (const selectedAddr of selectedAddresses) {
        const selectedStandardizedAddr = standardizeAddress(selectedAddr);
        if (expenseStandardizedAddress === selectedStandardizedAddr) {
          addressMatches = true;
          break;
        }
      }

      if (!addressMatches) {
        return false;
      }
    }

    // ДОПОЛНИТЕЛЬНЫЕ ПРОВЕРКИ
    // Исключаем записи с пустой статьей или нулевой суммой
    if (!expense.статья || expense.статья.trim() === '' ||
      !expense.наименование || expense.наименование.trim() === '' ||
      Math.abs(expense.сумма) < 0.01) {
      return false;
    }

    return true;
  });
}

function getFilteredSalaryOfficeExpenses() {
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;
  if (!dateFrom || !dateTo) return [];

  // Парсим даты из формата YYYY-MM-DD
  const fromDate = parseDateFromInput(dateFrom);
  const toDate = parseDateFromInput(dateTo);

  if (!fromDate || !toDate) return [];

  // Определяем вчерашний день (начало дня)
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  yesterday.setHours(0, 0, 0, 0);

  // Ограничиваем конечную дату началом вчерашнего дня
  // (чтобы сегодняшний день не учитывался)
  const maxAllowedDate = toDate > yesterday ? yesterday : toDate;

  // Проверяем, что начальная дата не позже конечной
  if (fromDate > maxAllowedDate) return [];

  const result = [];
  let processedWeeks = new Set();
  const weeklyData = {};

  salaryOfficeData.forEach(item => {
    if (!item.неделя) return;
    if (!weeklyData[item.неделя]) {
      weeklyData[item.неделя] = {
        сотрудники: [],
        месяц: item.месяц,
        год: item.год,
        дней_в_месяце: item.дней_в_месяце
      };
    }
    weeklyData[item.неделя].сотрудники.push(item);
  });

  for (const [weekStr, weekData] of Object.entries(weeklyData)) {
    try {
      const weekParts = weekStr.split(' - ');
      if (weekParts.length !== 2) continue;

      // Парсим даты недели (формат DD.MM.YY)
      const weekStart = parseWeekDate(weekParts[0].trim());
      const weekEnd = parseWeekDate(weekParts[1].trim());

      if (!weekStart || !weekEnd) continue;

      // Проверяем, пересекается ли неделя с допустимым диапазоном дат
      const weekInPeriod = (weekStart >= fromDate && weekStart <= maxAllowedDate) ||
        (weekEnd >= fromDate && weekEnd <= maxAllowedDate) ||
        (weekStart <= fromDate && weekEnd >= fromDate);

      if (weekInPeriod) {
        processedWeeks.add(weekStr);

        // Определяем фактическое пересечение недели с периодом
        const weekStartInPeriod = weekStart < fromDate ? fromDate : weekStart;
        const weekEndInPeriod = weekEnd > maxAllowedDate ? maxAllowedDate : weekEnd;

        // Рассчитываем количество дней в неделе, которые попадают в период
        const weekDaysInPeriod = Math.ceil((weekEndInPeriod - weekStartInPeriod) / (1000 * 60 * 60 * 24)) + 1;

        // Исключаем недели, которые полностью в будущем
        if (weekDaysInPeriod <= 0) continue;

        weekData.сотрудники.forEach(item => {
          const totalAmount = item.исходные_данные?.итого || 0;
          const officeSalary = item.исходные_данные?.оф_зп || 0;
          const coefficient = item.исходные_данные?.коэффициент || 0;
          const daysInMonth = item.дней_в_месяце || weekData.дней_в_месяце || 30;
          const dailySalary = (totalAmount + (officeSalary * coefficient)) / daysInMonth;
          const salaryForWeekDays = dailySalary * weekDaysInPeriod;

          result.push({
            неделя: weekStr,
            дней_в_неделе: weekDaysInPeriod,
            сотрудник: item.сотрудник,
            должность: item.должность,
            зарплата: salaryForWeekDays,
            исходные_данные: {
              итого: totalAmount,
              оф_зп: officeSalary,
              коэффициент: coefficient,
              дней_в_месяце: daysInMonth,
              дневная_зарплата: dailySalary
            },
            файл_источник: item.файл_источник
          });
        });
      }
    } catch (e) {
      console.error('Ошибка обработки недели:', weekStr, e);
    }
  }

  return result;
}

// НОВАЯ ФУНКЦИЯ: Получить выручку франшизы сопровождения за период
function getFranchiseSupportRevenueForPeriod(dateFrom, dateTo) {
  if (!dateFrom || !dateTo) return 0;

  const fromDate = new Date(dateFrom);
  const toDate = new Date(dateTo);

  const filteredSupportData = supportData.filter(item => {
    const itemDate = new Date(item.Дата.split('.').reverse().join('-'));
    return itemDate >= fromDate && itemDate <= toDate;
  });

  // Суммируем все оплаты от франчайзи
  return filteredSupportData.reduce((total, item) => {
    return total +
      (item["Оплаты от франчайзи за а/х"] || 0) +
      (item["Оплаты от франчайзи за ворота"] || 0) +
      (item["Оплаты от франчайзи за прочее"] || 0);
  }, 0);
}

// НОВАЯ ФУНКЦИЯ: Проверка, находится ли пользователь в режиме управляющего объекта
function isManagerMode(selectedObject) {
  return retailObjects.includes(selectedObject);
}

// НОВАЯ ФУНКЦИЯ: Проверка, находится ли пользователь в режиме "Все объекты + Все адреса"
function isAllObjectsAllAddressesMode(selectedObject, selectedAddresses) {
  return (!selectedObject || selectedObject === '') &&
    (!selectedAddresses || selectedAddresses.length === 0);
}

// ОБНОВЛЕННАЯ ФУНКЦИЯ: showRevenueDetailsByAddress() с поддержкой всех режимов
function showRevenueDetailsByAddress() {
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();
  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;

  // Проверяем, находится ли пользователь в нужном режиме
  const isAllObjectsAllAddresses = isAllObjectsAllAddressesMode(selectedObject, selectedAddresses);
  const isAllRetailAllAddresses = (selectedObject === 'all_retail' || selectedObject === '') &&
    (!selectedAddresses || selectedAddresses.length === 0);
  const isFranchiseSupport = selectedObject === 'Команда розницы франшиз';
  const isManagerModeActive = isManagerMode(selectedObject);

  if (!isAllObjectsAllAddresses && !isAllRetailAllAddresses && !isFranchiseSupport && !isManagerModeActive) {
    alert('Детализация выручки доступна только в режиме "Все объекты + Все адреса", "Вся розница + Все адреса", "Команда розницы франшиз" или для отдельного управляющего');
    return;
  }

  if (isAllObjectsAllAddresses) {
    // Детализация для всех объектов (4 столбца)
    showAllObjectsRevenueDetails(dateFrom, dateTo);
  } else if (isAllRetailAllAddresses) {
    // Детализация для всей розницы
    showRetailRevenueDetails(dateFrom, dateTo);
  } else if (isFranchiseSupport) {
    // Детализация для франшизы сопровождения
    showFranchiseSupportRevenueDetails(dateFrom, dateTo);
  } else if (isManagerModeActive) {
    // Детализация для конкретного управляющего
    showManagerRevenueDetails(selectedObject, dateFrom, dateTo);
  }
}

// НОВАЯ ФУНКЦИЯ: Детализация выручки розницы
function showRetailRevenueDetails(dateFrom, dateTo) {
  // Получаем отфильтрованные данные (уже в дневном формате)
  let filteredData = allData.filter(row => {
    const address = String(row.Адрес || '').trim();
    return !address.toLowerCase().includes('франшиза роялти');
  });

  // Фильтруем по дате
  if (dateFrom && dateTo) {
    filteredData = filteredData.filter(row => {
      const rowDateStr = row.Дата;
      if (!rowDateStr) return true;
      try {
        const rowDate = new Date(rowDateStr.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        return rowDate >= fromDate && rowDate <= toDate;
      } catch (e) {
        return true;
      }
    });
  }

  // Фильтруем только розницу
  filteredData = filteredData.filter(row => retailObjects.includes(row.Объект));

  // Группируем по адресам
  const revenueByAddress = {};
  filteredData.forEach(row => {
    const address = row.Адрес;
    const revenue = row.Выручка || 0;

    if (address) {
      if (!revenueByAddress[address]) {
        revenueByAddress[address] = 0;
      }
      revenueByAddress[address] += revenue;
    }
  });

  // Преобразуем в массив и сортируем по убыванию
  const sortedRevenue = Object.entries(revenueByAddress)
    .map(([address, revenue]) => ({ address, revenue }))
    .sort((a, b) => b.revenue - a.revenue);

  // Создаем график
  createRetailRevenueChart(sortedRevenue, dateFrom, dateTo);
}

// НОВАЯ ФУНКЦИЯ: Детализация выручки франшизы сопровождения
function showFranchiseSupportRevenueDetails(dateFrom, dateTo) {
  if (!dateFrom || !dateTo) {
    alert('Пожалуйста, выберите период дат');
    return;
  }

  const fromDate = new Date(dateFrom);
  const toDate = new Date(dateTo);

  // Фильтруем данные по дате
  const filteredSupportData = supportData.filter(item => {
    const itemDate = new Date(item.Дата.split('.').reverse().join('-'));
    return itemDate >= fromDate && itemDate <= toDate;
  });

  if (filteredSupportData.length === 0) {
    alert('Нет данных по оплатам франчайзи за выбранный период');
    return;
  }

  // Сортируем по дате
  filteredSupportData.sort((a, b) => {
    const dateA = new Date(a.Дата.split('.').reverse().join('-'));
    const dateB = new Date(b.Дата.split('.').reverse().join('-'));
    return dateA - dateB;
  });

  // Создаем график
  createFranchiseSupportRevenueChart(filteredSupportData, dateFrom, dateTo);
}

