function populateFilters(data) {

  const filteredData = data;

  allWeeks = [...new Set(filteredData.map(row => row.Неделя || row['﻿Неделя']))].filter(Boolean);

  allWeeks.sort((a, b) => {
    const dateA = new Date(a.split(' - ')[0].split('.').reverse().join('-'));
    const dateB = new Date(b.split(' - ')[0].split('.').reverse().join('-'));
    return dateA - dateB;
  });

  const objects = [...new Set(filteredData.map(row => row.Объект))]
    .filter(Boolean)
    .filter(obj => obj !== "Продажа объекта/агентские");

  const objectsSelect = document.getElementById('objectSelect');

  // Если объекты уже заданы в HTML в правильном порядке, не перезаписываем их
  // Просто добавляем только те объекты из данных, которых еще нет в списке
  const existingObjects = Array.from(objectsSelect.options)
    .map(opt => opt.value)
    .filter(value => value && value !== '' && value !== 'all_retail');

  // Добавляем только те объекты из данных, которых еще нет в списке
  objects.forEach(obj => {
    if (!existingObjects.includes(obj)) {
      const option = document.createElement('option');
      option.value = obj;
      option.textContent = obj;
      objectsSelect.appendChild(option);
    }
  });

  const addressSelect = document.getElementById('addressSelect');

  // Если адреса уже заданы в HTML (в нужном порядке), не перезаписываем их
  // Просто добавляем динамически найденные адреса, которых еще нет
  const existingAddresses = Array.from(addressSelect.options)
    .map(opt => opt.value)
    .filter(value => value && value !== '');

  // Собираем уникальные адреса из данных
  const addressesFromData = [...new Set(filteredData.map(row => row.Адрес))]
    .filter(Boolean)
    .filter(address => {
      const addr = String(address).trim();
      return !addr.toLowerCase().includes('франшиза роялти');
    });

  // Добавляем только те адреса, которых еще нет в списке
  addressesFromData.forEach(address => {
    if (!existingAddresses.includes(address)) {
      const option = document.createElement('option');
      option.value = address;
      option.textContent = address;
      addressSelect.appendChild(option);
    }
  });

  document.getElementById('filters').style.display = 'flex';

  objectsSelect.addEventListener('change', function () {
    updateAddressFilter(this.value, data);
    applyFilters();
  });

  addressSelect.addEventListener('change', function () {
    updateSelectedInfo('addressSelected', this);
    applyFilters();
  });

  updateSelectedInfo('addressSelected', addressSelect);

  // АВТОМАТИЧЕСКОЕ ОПРЕДЕЛЕНИЕ ДАТ - УЛУЧШЕННАЯ ВЕРСИЯ
  const dateTo = document.getElementById('dateTo');
  const dateFrom = document.getElementById('dateFrom');

  if (filteredData.length > 0) {
    let minDate = null;
    let maxDate = null;

    // 1. Ищем даты в основных данных (уже преобразованных в дневные)
    filteredData.forEach(row => {
      if (row.Дата) {
        try {
          const rowDate = new Date(row.Дата.split('.').reverse().join('-'));
          if (!minDate || rowDate < minDate) minDate = rowDate;
          if (!maxDate || rowDate > maxDate) maxDate = rowDate;
        } catch (e) {
          console.log('Ошибка обработки даты в основном наборе:', row.Дата, e);
        }
      }
      // Также проверяем недели на случай, если есть записи без дат
      else if (row.Неделя || row['﻿Неделя']) {
        try {
          const weekStr = row.Неделя || row['﻿Неделя'];
          if (weekStr) {
            const [startStr] = weekStr.split(' - ');
            const weekStartDate = new Date(startStr.trim().split('.').reverse().join('-'));
            if (!minDate || weekStartDate < minDate) minDate = weekStartDate;

            // Добавляем 6 дней для конца недели
            const weekEndDate = new Date(weekStartDate);
            weekEndDate.setDate(weekEndDate.getDate() + 6);
            if (!maxDate || weekEndDate > maxDate) maxDate = weekEndDate;
          }
        } catch (e) {
          console.log('Ошибка обработки недели:', row.Неделя || row['﻿Неделя'], e);
        }
      }
    });

    // 2. Ищем даты в зарплатных данных (из поля неделя)
    salaryOfficeData.forEach(item => {
      if (item.неделя) {
        try {
          const weekParts = item.неделя.split(' - ');
          if (weekParts.length === 2) {
            const weekStart = new Date(weekParts[0].trim().split('.').reverse().join('-'));
            const weekEnd = new Date(weekParts[1].trim().split('.').reverse().join('-'));

            if (!minDate || weekStart < minDate) minDate = weekStart;
            if (!maxDate || weekEnd > maxDate) maxDate = weekEnd;
          }
        } catch (e) {
          console.log('Ошибка обработки недели в зарплатных данных:', item.неделя, e);
        }
      }
    });

    // 3. Ищем даты в supportData
    if (supportData && supportData.length > 0) {
      supportData.forEach(item => {
        if (item.Дата) {
          try {
            const itemDate = new Date(item.Дата.split('.').reverse().join('-'));
            if (!minDate || itemDate < minDate) minDate = itemDate;
            if (!maxDate || itemDate > maxDate) maxDate = itemDate;
          } catch (e) {
            console.log('Ошибка обработки даты в supportData:', item.Дата, e);
          }
        }
      });
    }

    // 4. Устанавливаем даты по умолчанию
    if (minDate && maxDate) {
      // Форматируем даты для input type="date" (YYYY-MM-DD)
      const formatDateForInput = (date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
      };

      dateFrom.value = formatDateForInput(minDate);
      dateTo.value = formatDateForInput(maxDate);

      console.log('Автоматически установлен период:',
        minDate.toLocaleDateString('ru-RU'), '-',
        maxDate.toLocaleDateString('ru-RU'));
      console.log('В формате input:', dateFrom.value, '-', dateTo.value);

      // Для удобства пользователя устанавливаем фокус на конечную дату
      dateTo.focus();
      dateTo.blur(); // Снимаем фокус
    } else {
      // Если не нашли дат, ставим текущий месяц
      const today = new Date();
      const monthAgo = new Date();
      monthAgo.setMonth(monthAgo.getMonth() - 1);

      const formatDateForInput = (date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
      };

      dateFrom.value = formatDateForInput(monthAgo);
      dateTo.value = formatDateForInput(today);

      console.log('Установлен период по умолчанию (текущий месяц):',
        monthAgo.toLocaleDateString('ru-RU'), '-',
        today.toLocaleDateString('ru-RU'));
    }
  } else {
    // Если нет данных, ставим текущий месяц
    const today = new Date();
    const monthAgo = new Date();
    monthAgo.setMonth(monthAgo.getMonth() - 1);

    const formatDateForInput = (date) => {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    };

    dateFrom.value = formatDateForInput(monthAgo);
    dateTo.value = formatDateForInput(today);

    console.log('Нет данных. Установлен период по умолчанию (текущий месяц):',
      monthAgo.toLocaleDateString('ru-RU'), '-',
      today.toLocaleDateString('ru-RU'));
  }

  // Добавляем обработчики для полей дат
  dateFrom.addEventListener('change', function () {
    // Проверяем, чтобы начальная дата не была позже конечной
    if (dateTo.value && this.value > dateTo.value) {
      dateTo.value = this.value;
    }
    applyFilters();
  });

  dateTo.addEventListener('change', function () {
    // Проверяем, чтобы конечная дата не была раньше начальной
    if (dateFrom.value && this.value < dateFrom.value) {
      dateFrom.value = this.value;
    }
    applyFilters();
  });
}

function updateSelectedInfo(containerId, selectElement) {
  const selectedOptions = Array.from(selectElement.selectedOptions)
    .map(option => option.value)
    .filter(value => value && value !== '');

  const container = document.getElementById(containerId);
  if (selectedOptions.length > 0) {
    container.textContent = `Выбрано: ${selectedOptions.length}`;
    container.title = selectedOptions.join(', ');
  } else {
    container.textContent = 'Все';
    container.title = '';
  }
}

// ИСПРАВЛЕННАЯ ФУНКЦИЯ updateAddressFilter() ДЛЯ КОРРЕКТНОЙ РАБОТЫ
function updateAddressFilter(selectedObject, data) {
  const addressSelect = document.getElementById('addressSelect');
  const currentSelected = Array.from(addressSelect.selectedOptions).map(opt => opt.value);

  // Все доступные адреса из данных (для фильтрации по объекту)
  const allAddressesFromData = [...new Set(data.map(row => row.Адрес))].filter(Boolean);

  // Специальный порядок для "Вся розница"
  const retailAddressesOrder = [
    "ДМИТРОВСКОЕ",
    "ПЯТНИЦКОЕ",
    "Пятницкое шоссе 20",
    "ХИМКИ",
    "ШЕРЕМЕТЬЕВСКАЯ",
    "МИЧУРИНСКИЙ",
    "ЛОБАЧЕВСКОГО 37",
    "ЛОБАЧЕВСКОГО 92",
    "ЛОБАЧЕВСКОГО 19",
    "РУБЛЕВКА91",
    "РУБЛЕВСКОЕ вл.4",
    "Минская",
    "ПРАВОБЕРЕЖНАЯ",
    "Носовихинское",
    "Пр Мира 94 А",
    "ТТК",
    "МЫТИЩИ",
    "ПЛЕЩЕЕВА",
    "ВЕРНАДСКОГО",
    "НОВОЯСЕНЕВСКИЙ",
    "ПРОФСОЮЗНАЯ",
    "Дзержинский, Угрешская",
    "ЗАГОРОДНОЕ",
    "ПРИВОЛЬНАЯ",
    "ЛЮБЛИНСКАЯ 135",
    "Каспийская",
    "КАШИРСКОЕ 24",
    "Коломенский пр-д",
    "ВДНХ",
    "Куликовская",
    "Чертановская",
    "СПб, Маршала Жукова",
    "ПАПЕРНИКА вл.22",
    "ПРИШВИНА",
    "СЕРПУХОВ"
  ];

  let filteredAddresses = [];
  let displayAddresses = [];

  if (selectedObject === 'all_retail') {
    // Для "Вся розница" показываем адреса в специальном порядке
    filteredAddresses = retailAddressesOrder;
    displayAddresses = retailAddressesOrder;
  } else if (selectedObject) {
    // Для конкретного объекта фильтруем адреса
    filteredAddresses = [...new Set(data
      .filter(row => row.Объект === selectedObject)
      .map(row => row.Адрес))].filter(Boolean);

    // Сохраняем порядок из HTML для других объектов
    const htmlOptions = Array.from(addressSelect.options)
      .map(opt => opt.value)
      .filter(value => value && value !== '');

    displayAddresses = htmlOptions.filter(addr => filteredAddresses.includes(addr));

    // Добавляем адреса, которых нет в HTML
    const missingAddresses = filteredAddresses.filter(addr => !displayAddresses.includes(addr));
    displayAddresses = [...displayAddresses, ...missingAddresses];
  } else {
    // Для "Все объекты" показываем все адреса в порядке из HTML
    const htmlOptions = Array.from(addressSelect.options)
      .map(opt => opt.value)
      .filter(value => value && value !== '');

    filteredAddresses = htmlOptions;
    displayAddresses = htmlOptions;
  }

  // Обновляем список адресов
  addressSelect.innerHTML = '<option value="">Все адреса</option>';

  if (selectedObject === 'all_retail') {
    // Для "Вся розница" используем специальный порядок
    displayAddresses.forEach(address => {
      const option = document.createElement('option');
      option.value = address;
      option.textContent = address;
      if (currentSelected.includes(address)) {
        option.selected = true;
      }
      addressSelect.appendChild(option);
    });
  } else {
    // Для других случаев сохраняем существующий порядок
    displayAddresses.forEach(address => {
      if (filteredAddresses.includes(address)) {
        const option = document.createElement('option');
        option.value = address;
        option.textContent = address;
        if (currentSelected.includes(address)) {
          option.selected = true;
        }
        addressSelect.appendChild(option);
      }
    });
  }

  updateSelectedInfo('addressSelected', addressSelect);
}

function getSelectedObject() {
  const objectSelect = document.getElementById('objectSelect');
  return objectSelect.value !== '' ? objectSelect.value : null;
}

function getSelectedAddresses() {
  const addressSelect = document.getElementById('addressSelect');
  const selectedAddresses = Array.from(addressSelect.selectedOptions)
    .map(option => option.value)
    .filter(value => value && value !== '');
  return selectedAddresses.length > 0 ? selectedAddresses : null;
}

// ИСПРАВЛЕННАЯ ФУНКЦИЯ applyFilters() (ОДНА ВЕРСИЯ!)
// ИСПРАВЛЕННАЯ ФУНКЦИЯ: applyFilters() - корректная фильтрация
function applyFilters() {
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();

  console.log('=== applyFilters ===');
  console.log('selectedObject:', selectedObject);
  console.log('selectedAddresses:', selectedAddresses);
  console.log('Всего записей в allData:', allData.length);

  let filteredData = [...allData];

  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;

  console.log('Период фильтрации:', dateFrom, '-', dateTo);

  if (dateFrom && dateTo) {
    const fromDate = new Date(dateFrom);
    const toDate = new Date(dateTo);

    console.log('Даты для фильтрации (объекты):', fromDate.toLocaleDateString(), '-', toDate.toLocaleDateString());

    filteredData = filteredData.filter(row => {
      let rowDate = null;

      // Пытаемся получить дату из поля Дата
      if (row.Дата) {
        try {
          rowDate = new Date(row.Дата.split('.').reverse().join('-'));
        } catch (e) {
          console.error('Ошибка обработки даты:', row.Дата, e);
        }
      }

      // Если нет даты, пытаемся получить из недели
      if (!rowDate && (row.Неделя || row['﻿Неделя'])) {
        try {
          const weekStr = row.Неделя || row['﻿Неделя'];
          if (weekStr) {
            const [startStr] = weekStr.split(' - ');
            rowDate = new Date(startStr.trim().split('.').reverse().join('-'));
          }
        } catch (e) {
          console.error('Ошибка обработки недели:', row.Неделя || row['﻿Неделя'], e);
        }
      }

      if (rowDate) {
        // Проверяем, попадает ли дата в диапазон
        const inRange = rowDate >= fromDate && rowDate <= toDate;
        if (!inRange) {
          console.log('Исключена запись:', row.Дата, row.Объект, row.Адрес, 'Дата:', rowDate.toLocaleDateString());
        }
        return inRange;
      }

      // Если не удалось определить дату, исключаем запись
      console.log('Запись без даты исключена:', row.Объект, row.Адрес);
      return false;
    });
  }

  console.log('После фильтрации по дате осталось записей:', filteredData.length);

  // СНАЧАЛА фильтруем по адресам, ЕСЛИ они выбраны
  if (selectedAddresses && selectedAddresses.length > 0) {
    const validAddresses = selectedAddresses.filter(addr => addr && addr !== '');

    if (validAddresses.length > 0) {
      filteredData = filteredData.filter(row => {
        const rowAddress = String(row.Адрес || '').trim();

        if (!rowAddress) return false;

        // Стандартизируем адрес строки
        const rowStandardizedAddress = standardizeAddress(rowAddress);

        // Проверяем совпадения
        for (const selectedAddr of validAddresses) {
          const selectedStandardizedAddr = standardizeAddress(selectedAddr);

          // Точное совпадение оригинальных адресов
          if (rowAddress === selectedAddr) return true;

          // Совпадение стандартизированных адресов
          if (rowStandardizedAddress === selectedStandardizedAddr) return true;

          // Сравнение без учета регистра
          if (rowAddress.toLowerCase() === selectedAddr.toLowerCase()) return true;

          // Частичное совпадение
          if (rowAddress.includes(selectedAddr) || selectedAddr.includes(rowAddress)) return true;
        }

        return false;
      });

      console.log('После фильтрации по адресам осталось записей:', filteredData.length);
    }
  }

  // ПОТОМ фильтруем по объекту, ЕСЛИ он выбран
  if (selectedObject) {
    if (selectedObject === 'all_retail') {
      filteredData = filteredData.filter(row => retailObjects.includes(row.Объект));
    } else {
      filteredData = filteredData.filter(row => row.Объект === selectedObject);
    }
    console.log('После фильтрации по объекту осталось записей:', filteredData.length);
  }

  // Отладочная информация
  if (filteredData.length > 0) {
    console.log('Примеры отфильтрованных данных:');
    filteredData.slice(0, 5).forEach((row, i) => {
      console.log(`${i + 1}. Дата: ${row.Дата}, Объект: ${row.Объект}, Адрес: ${row.Адрес}, Выручка: ${row.Выручка || 0}`);
    });

    // Подсчет агрегированных значений для проверки
    let totalRevenue = 0;
    filteredData.forEach(row => {
      totalRevenue += (row.Выручка || 0) + (row['Выручка Сайт'] || 0);
    });
    console.log('Ожидаемая агрегированная выручка за период:', totalRevenue);
  }

  updateSelectionInfo(dateFrom, dateTo, selectedObject, selectedAddresses, filteredData.length);

  if (filteredData.length > 0) {
    buildChart(filteredData, selectedObject, selectedAddresses);
  } else {
    document.getElementById('chart').innerHTML = '<div style="text-align: center; padding: 50px; color: #666;">Нет данных для выбранных фильтров</div>';
  }
}

function updateSelectionInfo(dateFrom, dateTo, object, addresses, count) {
  let info = `Показано записей: ${count}`;
  if (dateFrom && dateTo) {
    info += ` | Период: ${formatDateForDisplay(dateFrom)} - ${formatDateForDisplay(dateTo)}`;
  }
  if (object) {
    info += ` | Объект: ${object === 'all_retail' ? 'Вся розница' : object}`;
  }
  if (addresses) {
    info += ` | Адресов: ${addresses.length}`;
  }
  document.getElementById('fileInfo').textContent = info;
}

// НОВАЯ ФУНКЦИЯ: Автоматическое определение адресов по управляющему для выбранного периода
function getAddressesByManagerForPeriod(managerName, dateFrom, dateTo) {
  let filteredData = allData.filter(row => {
    const object = String(row.Объект || '').trim();
    const address = String(row.Адрес || '').trim();

    // Фильтруем по управляющему и исключаем франшизу роялти
    return object === managerName &&
      !address.toLowerCase().includes('франшиза роялти');
  });

  // Фильтруем по дате
  if (dateFrom && dateTo) {
    filteredData = filteredData.filter(row => {
      const rowDateStr = row.Дата;
      if (!rowDateStr) return true;
      try {
        const rowDate = new Date(rowDateStr.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        return rowDate >= fromDate && rowDate <= toDate;
      } catch (e) {
        return true;
      }
    });
  }

  // Получаем уникальные адреса из отфильтрованных данных
  const uniqueAddresses = [...new Set(filteredData
    .map(row => row.Адрес)
    .filter(address => address && address.trim() !== '')
  )];

  return uniqueAddresses;
}

// НОВАЯ ФУНКЦИЯ: Детализация выручки для управляющего с автоматическим определением адресов
function showManagerRevenueDetails(managerName, dateFrom, dateTo) {
  // Получаем все адреса, относящиеся к этому управляющему ЗА ВЫБРАННЫЙ ПЕРИОД
  const managerAddresses = getAddressesByManagerForPeriod(managerName, dateFrom, dateTo);

  if (managerAddresses.length === 0) {
    alert(`Нет адресов для управляющего "${managerName}" за выбранный период ${dateFrom || ''} - ${dateTo || ''}`);
    return;
  }

  // Получаем отфильтрованные данные (уже в дневном формате)
  let filteredData = allData.filter(row => {
    const address = String(row.Адрес || '').trim();
    const object = String(row.Объект || '').trim();

    // Фильтруем по управляющему и исключаем франшизу роялти
    return object === managerName &&
      !address.toLowerCase().includes('франшиза роялти');
  });

  // Фильтруем по дате
  if (dateFrom && dateTo) {
    filteredData = filteredData.filter(row => {
      const rowDateStr = row.Дата;
      if (!rowDateStr) return true;
      try {
        const rowDate = new Date(rowDateStr.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        return rowDate >= fromDate && rowDate <= toDate;
      } catch (e) {
        return true;
      }
    });
  }

  if (filteredData.length === 0) {
    alert(`Нет данных о выручке для управляющего "${managerName}" за выбранный период ${dateFrom || ''} - ${dateTo || ''}`);
    return;
  }

  console.log(`=== Данные для управляющего: ${managerName} ===`);
  console.log(`Период: ${dateFrom} - ${dateTo}`);
  console.log(`Найдено записей: ${filteredData.length}`);
  console.log(`Уникальные адреса: ${managerAddresses.join(', ')}`);

  // Группируем по адресам
  const revenueByAddress = {};
  filteredData.forEach(row => {
    const address = row.Адрес;
    const revenue = row.Выручка || 0;

    if (address) {
      if (!revenueByAddress[address]) {
        revenueByAddress[address] = 0;
      }
      revenueByAddress[address] += revenue;
    }
  });

  // Преобразуем в массив и сортируем по убыванию
  const sortedRevenue = Object.entries(revenueByAddress)
    .map(([address, revenue]) => ({
      address,
      revenue,
      // Добавляем стандартизированный адрес для корректной сортировки
      standardizedAddress: standardizeAddress(address)
    }))
    .sort((a, b) => {
      // Сначала сортируем по выручке (по убыванию)
      if (b.revenue !== a.revenue) {
        return b.revenue - a.revenue;
      }
      // Если выручка равна, сортируем по названию адреса
      return a.standardizedAddress.localeCompare(b.standardizedAddress);
    });

  console.log(`Выручка по адресам:`);
  sortedRevenue.forEach(item => {
    console.log(`  ${item.address}: ${formatCurrency(item.revenue)}`);
  });

  // Создаем график
  createManagerRevenueChart(managerName, sortedRevenue, dateFrom, dateTo);
}

// НОВАЯ ФУНКЦИЯ: Создание графика выручки для управляющего
function createManagerRevenueChart(managerName, revenueData, dateFrom, dateTo) {
  if (currentChart) {
    currentChart.dispose();
    currentChart = null;
  }

  const chart = echarts.init(document.getElementById('chart'));
  currentChart = chart;

  // Подготавливаем данные для графика
  const addresses = revenueData.map(item => item.address);
  const revenues = revenueData.map(item => item.revenue);

  const option = {
    title: {
      text: `Выручка по адресам - ${managerName}`,
      subtext: dateFrom && dateTo ? `Период: ${formatDateForDisplay(dateFrom)} - ${formatDateForDisplay(dateTo)}` : '',
      left: 'center',
      textStyle: {
        fontSize: 16,
        fontWeight: 'bold'
      }
    },
    tooltip: {
      trigger: 'axis',
      axisPointer: {
        type: 'shadow'
      },
      formatter: function (params) {
        const data = params[0];
        const value = data.value;
        const address = data.name;
        const totalRevenue = revenues.reduce((sum, val) => sum + val, 0);
        const percentage = totalRevenue > 0 ? ((value / totalRevenue) * 100).toFixed(1) : 0;

        return `
          <div style="text-align: left; padding: 5px;">
            <strong>${address}</strong><br/>
            Управляющий: ${managerName}<br/>
            Выручка: ${formatCurrency(value)}<br/>
            Доля от общей: ${percentage}%
          </div>
        `;
      }
    },
    grid: {
      left: '5%',
      right: '5%',
      bottom: '15%',
      top: '15%',
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: addresses,
      axisLabel: {
        interval: 0,
        rotate: 45,
        fontSize: 11,
        margin: 10,
        formatter: function (value) {
          // Ограничиваем длину названия адреса
          return value.length > 20 ? value.substring(0, 20) + '...' : value;
        }
      },
      axisTick: {
        alignWithLabel: true
      }
    },
    yAxis: {
      type: 'value',
      scale: true,
      axisLabel: {
        formatter: formatCurrency
      }
    },
    series: [
      {
        name: 'Выручка',
        type: 'bar',
        barWidth: '60%',
        data: revenues.map((value, index) => ({
          value: value,
          itemStyle: {
            // Разные цвета для разных управляющих
            color: getManagerColor(managerName),
            // Градиент для визуального эффекта
            shadowBlur: 10,
            shadowColor: 'rgba(0, 0, 0, 0.3)'
          }
        })),
        label: {
          show: true,
          position: 'top',
          formatter: function (params) {
            return formatCurrency(params.value);
          },
          fontSize: 10,
          fontWeight: 'bold',
          color: '#333'
        },
        emphasis: {
          itemStyle: {
            shadowBlur: 20,
            shadowColor: 'rgba(0, 0, 0, 0.5)'
          }
        }
      }
    ],
    dataZoom: [
      {
        type: 'inside',
        xAxisIndex: 0,
        start: 0,
        end: 100
      },
      {
        show: true,
        xAxisIndex: 0,
        type: 'slider',
        bottom: 10,
        start: 0,
        end: 100,
        height: 20
      }
    ]
  };

  chart.setOption(option);

  // Обновляем статистику
  const totalRevenue = revenues.reduce((sum, value) => sum + value, 0);
  const avgRevenue = revenues.length > 0 ? totalRevenue / revenues.length : 0;
  const maxRevenue = Math.max(...revenues);
  const minRevenue = Math.min(...revenues);
  const maxAddress = revenueData.find(item => item.revenue === maxRevenue)?.address || 'Н/Д';
  const minAddress = revenueData.find(item => item.revenue === minRevenue)?.address || 'Н/Д';

  document.getElementById('statsInfo').innerHTML = `
    <div class="stat-item" style="background-color: ${getManagerColor(managerName)}30; border-left: 4px solid ${getManagerColor(managerName)};">
      <strong>${managerName}</strong>
    </div>
    <div class="stat-item">Период: ${dateFrom ? formatDateForDisplay(dateFrom) : 'н/д'} - ${dateTo ? formatDateForDisplay(dateTo) : 'н/д'}</div>
    <div class="stat-item">Адресов: ${revenues.length}</div>
    <div class="stat-item">Записей: ${allData.filter(row => row.Объект === managerName &&
    (!dateFrom || !dateTo || (row.Дата && isDateInRange(row.Дата, dateFrom, dateTo)))).length}</div>
    <div class="stat-item">Общая выручка: ${formatCurrency(totalRevenue)}</div>
    <div class="stat-item">Средняя выручка: ${formatCurrency(avgRevenue)}</div>
    <div class="stat-item">Максимальная: ${formatCurrency(maxRevenue)} (${maxAddress})</div>
    <div class="stat-item">Минимальная: ${formatCurrency(minRevenue)} (${minAddress})</div>
  `;

  window.addEventListener('resize', function () {
    chart.resize();
  });
}

// НОВАЯ ФУНКЦИЯ: Проверка, находится ли дата в диапазоне
function isDateInRange(dateStr, dateFrom, dateTo) {
  if (!dateStr || !dateFrom || !dateTo) return true;
  try {
    const date = new Date(dateStr.split('.').reverse().join('-'));
    const fromDate = new Date(dateFrom);
    const toDate = new Date(dateTo);
    return date >= fromDate && date <= toDate;
  } catch (e) {
    return false;
  }
}

// НОВАЯ ФУНКЦИЯ: Получение цвета для управляющего
function getManagerColor(managerName) {
  const colorMap = {
    "Козубенко Денис": "#4CAF50",      // Зеленый
    "Сенатов Кирилл": "#2196F3",       // Синий
    "Большаков Максим": "#FF9800",     // Оранжевый
    "Мозговой Филипп": "#9C27B0",      // Фиолетовый
    "Данилов Алексей": "#F44336",      // Красный
    "Ичко Роман": "#00BCD4",           // Голубой
    "Юрлов Денис": "#FF5722",          // Глубокий оранжевый
    "Неизвестный управляющий": "#607D8B" // Серо-синий
  };
  return colorMap[managerName] || "#4CAF50";
}

// ОБНОВЛЕННАЯ ФУНКЦИЯ: Форматирование даты для отображения
function formatDateForDisplay(dateStr) {
  if (!dateStr) return '';
  try {
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      return `${parts[2]}.${parts[1]}.${parts[0]}`;
    }
    return dateStr;
  } catch (e) {
    return dateStr;
  }
}

function buildChart(data, object, addresses) {
  // Удаляем второй график если он есть
  const secondChart = document.getElementById('secondChart');
  if (secondChart) {
    secondChart.remove();
  }

  if (currentChart) {
    currentChart.dispose();
    currentChart = null;
  }

  // Получаем данные прошлого года для сравнения (если режим включен)
  let prevYearData = null;
  if (comparisonMode) {
      const dateFrom = document.getElementById('dateFrom').value;
      const dateTo = document.getElementById('dateTo').value;
      if (dateFrom && dateTo) {
          prevYearData = getPreviousYearData(dateFrom, dateTo, object, addresses);
      }
  }

  // Получаем данные предыдущего периода для сравнения (если режим включен)
  let prevPeriodData = null;
  if (comparisonMode) {
      const dateFrom = document.getElementById('dateFrom').value;
      const dateTo = document.getElementById('dateTo').value;
      if (dateFrom && dateTo) {
          prevPeriodData = getPreviousPeriodData(dateFrom, dateTo, object, addresses);
      }
  }

  const chart = echarts.init(document.getElementById('chart'));
  currentChart = chart;

  const aggregated = aggregateCategories(data);

  // ИСПРАВЛЕНО: Добавляем "Выручка Оборудование" в общую выручку
  const regularRevenue = (aggregated['Выручка'] || 0) +
    (aggregated['Выручка Сайт'] || 0) +
    (aggregated['Выручка Оборудование'] || 0);

  const franchBonus = aggregated['Команда розницы франшиз бонус'] || 0;
  const totalRevenue = regularRevenue + franchBonus;

  console.log('Агрегированные данные для графика:');
  console.log('- Выручка (основная):', aggregated['Выручка'] || 0);
  console.log('- Выручка Сайт:', aggregated['Выручка Сайт'] || 0);
  console.log('- Выручка Оборудование:', aggregated['Выручка Оборудование'] || 0);
  console.log('- Регулярная выручка (сумма):', regularRevenue);
  console.log('- Команда розницы франшиз бонус:', franchBonus);
  console.log('- Общая выручка:', totalRevenue);

  let categories = [
    "Выручка",
    "Автохимия",
    "Коммунальные расходы",
    "Аренда",
    "Зарплата",
    "Комиссии",
    "Налоги",
    "НДС",
    "Прочие",
    "Неделимый расход",
    "Чистая прибыль"
  ];

  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();

  const isAllObjectsAllAddresses = (!selectedObject || selectedObject === '') &&
    (!selectedAddresses || selectedAddresses.length === 0);
  const isFranchObject = selectedObject === 'Команда розницы франшиз';

  const isAllObjects = !object || object === '';
  const isAllAddresses = !addresses || addresses.length === 0;
  const showCompanyExpenses = isAllObjects && isAllAddresses;

  if (showCompanyExpenses) {
    categories.splice(categories.indexOf("Чистая прибыль"), 0, "Общий расход", "З/п офис", "Инвестиционный расход");
  }

  // Получаем значения для расчета скорректированного налога и НДС
  const adjustedGeneralExpense = getAdjustedGeneralExpenseForDateRange();
  const adjustedConstruction = getAdjustedConstructionExpenseForDateRange();
  const salaryOffice = calculateSalaryForPeriod();
  
  // Рассчитываем налог на прибыль (25% от скорректированных расходов) - тут поменял, без Инвестиционный расход (в налогах не участвует)
  const profitTax = (adjustedGeneralExpense + salaryOffice) * 0.25;
  
  // Исходные налоги из данных
  const originalTax = aggregated['Налоги'] || 0;
  
  // Скорректированные налоги = исходные налоги - налог на прибыль
  const adjustedTax = originalTax - profitTax;
  
  // ========== КОРРЕКТИРОВКА НДС ==========
  // Собираем сумму НДС ТОЛЬКО из Общего расхода (исключая Инвестиционный расход)
  let totalInputVat = 0;

  // Суммируем исходящий НДС из Общего расхода (без команды, исключая Инвестиционный расход)
  otherExpensesData.forEach(expense => {
      if (expense.мойка !== "Общий расход") return;
      if (expense.команда && expense.команда.trim() !== '') return;
      if (expense.статья === "Инвестиционный расход нового объекта") return;
      
      const expenseDate = new Date(expense.дата.split('.').reverse().join('-'));
      const fromDate = new Date(document.getElementById('dateFrom').value);
      const toDate = new Date(document.getElementById('dateTo').value);
      if (expenseDate < fromDate || expenseDate > toDate) return;
      
      totalInputVat += expense.ндс_исходящий || 0;
  });

  // ========== УБИРАЕМ Инвестиционный расход ИЗ НДС ==========
  // НЕ суммируем НДС из Строительства (удаляем этот блок)

  // Исходный НДС из данных
  const originalVat = aggregated['НДС'] || 0;

  // Скорректированный НДС = исходный НДС + вычитаемый НДС (только из Общего расхода)
  const adjustedVat = originalVat + totalInputVat;

  console.log('=== КОРРЕКТИРОВКА НДС ===');
  console.log('Входной НДС (только из Общего расхода):', formatCurrency(totalInputVat));
  console.log('Исходный НДС:', formatCurrency(originalVat));
  console.log('Скорректированный НДС (без строительства):', formatCurrency(adjustedVat));

  console.log('=== КОРРЕКТИРОВКА НАЛОГОВ ===');
  console.log('Скорректированный Общий расход:', formatCurrency(adjustedGeneralExpense));
  console.log('З/п офис:', formatCurrency(salaryOffice));
  console.log('Скорректированное Инвестиционный расход:', formatCurrency(adjustedConstruction));
  console.log('Налог на прибыль (25%):', formatCurrency(profitTax));
  console.log('Исходные налоги:', formatCurrency(originalTax));
  console.log('Скорректированные налоги:', formatCurrency(adjustedTax));
  
  console.log('=== КОРРЕКТИРОВКА НДС ===');
  console.log('Входной НДС (из Общего расхода и Строительства):', formatCurrency(totalInputVat));
  console.log('Исходный НДС:', formatCurrency(originalVat));
  console.log('Скорректированный НДС (исходный + входной):', formatCurrency(adjustedVat));

  // Сохраняем значения для специального расчета
  let regularRevenueValue = 0;
  let otherExpensesSum = 0;
  let indivisibleExpenseValue = 0;
  let generalExpenseValue = 0;
  let salaryOfficeValue = 0;
  let constructionValue = 0;

  // Собираем значения для каждой категории
  const categoryValues = {};

  for (const cat of categories) {
    let value = 0;

    switch (cat) {
      case "Выручка":
        if (selectedObject === 'Команда розницы франшиз') {
          const dateFrom = document.getElementById('dateFrom').value;
          const dateTo = document.getElementById('dateTo').value;
          const supportRevenue = getFranchiseSupportRevenueForPeriod(dateFrom, dateTo);
          value = supportRevenue + franchBonus;
        } else {
          value = totalRevenue;
        }
        regularRevenueValue = value;
        break;

      case "Автохимия":
        value = (aggregated['Автохимия Шампунь Москва'] || 0) +
          (aggregated['Автохимия Шампунь СПБ'] || 0) +
          (aggregated['Автохимия Пена'] || 0) +
          (aggregated['Автохимия Юр. Лица'] || 0) +
          (aggregated['Автохимия Абонементы/сертификаты/подписки'] || 0);
        break;

      case "Коммунальные расходы":
        value = (aggregated['Коммунальные расходы'] || 0) +
          (aggregated['Коммунальные расходы Абонементы/сертификаты/подписки'] || 0);
        break;

      case "Аренда":
        value = aggregated['Аренда'] || 0;
        break;

      case "Зарплата":
        value = aggregated['Зарплата'] || 0;
        break;

      case "Комиссии":
        value = aggregated['Комиссии'] || 0;
        break;

      case "Налоги":
        if (showCompanyExpenses && isAllObjectsAllAddresses) {
          value = adjustedTax;
        } else {
          value = aggregated['Налоги'] || 0;
        }
        break;

      case "НДС":
        if (showCompanyExpenses && isAllObjectsAllAddresses) {
          value = adjustedVat;
        } else {
          value = aggregated['НДС'] || 0;
        }
        break;

      case "Прочие":
        const filteredExpenses = getFilteredOtherExpenses();
        value = filteredExpenses.reduce((sum, item) => sum + item.сумма, 0);
        break;

      case "Неделимый расход":
        value = getIndivisibleExpenseForDateRange(object, addresses);
        indivisibleExpenseValue = value;
        break;

      case "Общий расход":
        if (showCompanyExpenses) {
          if (isAllObjectsAllAddresses) {
            value = getAdjustedGeneralExpenseForDateRange();
          } else {
            value = getGeneralExpenseForDateRange();
          }
          generalExpenseValue = value;
        }
        break;

      case "З/п офис":
        if (showCompanyExpenses) {
          value = calculateSalaryForPeriod();
          salaryOfficeValue = value;
        }
        break;

      case "Инвестиционный расход":
        if (showCompanyExpenses) {
          if (isAllObjectsAllAddresses) {
            value = getAdjustedConstructionExpenseForDateRange();
          } else {
            value = getConstructionExpenseForDateRange();
          }
          constructionValue = value;
        }
        break;

      case "Чистая прибыль":
        value = 0;
        break;

      default:
        value = 0;
    }

    categoryValues[cat] = value;

    // Суммируем остальные расходы (исключая специальные категории)
    if (cat !== "Выручка" &&
      cat !== "Чистая прибыль" &&
      cat !== "Общий расход" &&
      cat !== "З/п офис" &&
      cat !== "Инвестиционный расход" &&
      cat !== "Неделимый расход" &&
      cat !== "Налоги" &&
      cat !== "НДС") {
      otherExpensesSum += value;
    }
  }

  // Строим водопадные данные для отображения
  const waterfallData = [];
  let currentLevel = 0;

  for (let i = 0; i < categories.length; i++) {
    const category = categories[i];
    const value = categoryValues[category];

    if (category === "Выручка") {
      waterfallData.push({
        value: value,
        start: 0,
        end: value,
        regularRevenue: regularRevenue,
        bonusRevenue: franchBonus,
        showBonus: (isAllObjectsAllAddresses || isFranchObject) && franchBonus > 0
      });
      currentLevel = value;
    }
    else if (category === "Чистая прибыль") {
      continue;
    }
    else {
      const start = currentLevel;
      currentLevel += value;
      waterfallData.push({
        value: value,
        start: start,
        end: currentLevel,
        category: category
      });
    }
  }

  // РАСЧЕТ ОПЕРАЦИОННОЙ ПРИБЫЛИ
  let finalOperatingProfit;

  if (isAllObjectsAllAddresses && showCompanyExpenses) {
      // Суммируем все расходы, кроме выручки
      const allExpenses = otherExpensesSum + indivisibleExpenseValue + generalExpenseValue + salaryOfficeValue + constructionValue;
      
      // Получаем скорректированные НДС и Налоги
      const adjustedVatValue = categoryValues["НДС"] || 0;
      const adjustedTaxValue = categoryValues["Налоги"] || 0;
      
      // Чистая прибыль = Выручка + Все расходы + Скорректированный НДС + Скорректированные налоги
      finalOperatingProfit = regularRevenueValue + allExpenses + adjustedVatValue + adjustedTaxValue;
      
      console.log('=== СПЕЦИАЛЬНЫЙ РАСЧЕТ (Все объекты + Все адреса) ===');
      console.log('Выручка:', formatCurrency(regularRevenueValue));
      console.log('Остальные расходы:', formatCurrency(otherExpensesSum));
      console.log('Неделимый расход:', formatCurrency(indivisibleExpenseValue));
      console.log('Скорректированный Общий расход:', formatCurrency(generalExpenseValue));
      console.log('З/п офис:', formatCurrency(salaryOfficeValue));
      console.log('Скорректированное Инвестиционный расход:', formatCurrency(constructionValue));
      console.log('Скорректированный НДС:', formatCurrency(adjustedVatValue));
      console.log('Скорректированные налоги:', formatCurrency(adjustedTaxValue));
      console.log('Итоговая Чистая прибыль:', formatCurrency(finalOperatingProfit));
  }
  else {
      // Стандартный расчет для остальных режимов
      finalOperatingProfit = currentLevel;
      console.log('=== СТАНДАРТНЫЙ РАСЧЕТ ===');
      console.log('Итоговая Чистая прибыль:', formatCurrency(finalOperatingProfit));
  }

  waterfallData.push({
      value: finalOperatingProfit,
      start: 0,
      end: finalOperatingProfit,
      category: "Чистая прибыль",
      isOperatingProfit: true
  });

  renderChart(
      chart,
      categories,
      waterfallData,
      object,
      addresses,
      showCompanyExpenses,
      totalRevenue,
      regularRevenue,
      franchBonus,
      finalOperatingProfit,
      isAllObjectsAllAddresses
  );
}

// ИСПРАВЛЕННАЯ ФУНКЦИЯ: Установка периода по умолчанию 
function setDefaultDateRange() {
  const dateTo = document.getElementById('dateTo');
  const dateFrom = document.getElementById('dateFrom');

  // Получаем текущую дату (сегодня)
  const today = new Date();

  // Определяем день недели (0 - воскресенье, 1 - понедельник...)
  const dayOfWeek = today.getDay();

  let startDate, endDate;

  if (dayOfWeek === 1) { // Если сегодня понедельник
    // Показываем прошлую неделю полностью

    // Находим понедельник прошлой недели
    const lastWeekMonday = new Date(today);
    lastWeekMonday.setDate(today.getDate() - 7);

    // Находим воскресенье прошлой недели (6 дней после понедельника)
    const lastWeekSunday = new Date(lastWeekMonday);
    lastWeekSunday.setDate(lastWeekMonday.getDate() + 6);

    startDate = lastWeekMonday;
    endDate = lastWeekSunday;
  } else {
    // Если сегодня не понедельник
    // Показываем текущую неделю с понедельника до вчерашнего дня

    // Находим понедельник текущей недели
    const daysToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    const currentWeekMonday = new Date(today);
    currentWeekMonday.setDate(today.getDate() + daysToMonday);

    // Находим вчерашний день
    const yesterday = new Date(today);
    yesterday.setDate(today.getDate() - 1);

    startDate = currentWeekMonday;
    endDate = yesterday;
  }

  // Форматируем даты для input type="date" (YYYY-MM-DD)
  const formatDateForInput = (date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Устанавливаем значения
  dateFrom.value = formatDateForInput(startDate);
  dateTo.value = formatDateForInput(endDate);

  console.log('Автоматически установлен период:');
  console.log('С:', startDate.toLocaleDateString('ru-RU'));
  console.log('По:', endDate.toLocaleDateString('ru-RU'));
  console.log('В формате input:', dateFrom.value, '-', dateTo.value);
  console.log('Сегодня день недели:', dayOfWeek, dayOfWeek === 1 ? '(понедельник)' : '(не понедельник)');
}

function aggregateCategories(data) {
  const aggregated = {};

  // Собираем все уникальные числовые поля
  const numericFields = new Set();

  // Проходим по всем данным и собираем поля
  data.forEach(row => {
    for (const key in row) {
      if (key !== 'Неделя' && key !== '﻿Неделя' && key !== 'Объект' && key !== 'Адрес' && key !== 'Дата') {
        if (typeof row[key] === 'number') {
          numericFields.add(key);
        }
      }
    }
  });

  // Инициализируем все числовые поля нулями
  numericFields.forEach(field => {
    aggregated[field] = 0;
  });

  // Агрегируем все данные без группировки по дням
  data.forEach(row => {
    for (const key in row) {
      if (key !== 'Неделя' && key !== '﻿Неделя' && key !== 'Объект' && key !== 'Адрес' && key !== 'Дата') {
        if (typeof row[key] === 'number') {
          aggregated[key] = (aggregated[key] || 0) + row[key];
        }
      }
    }
  });

  // Отладочная информация
  console.log('=== АГРЕГАЦИЯ ДАННЫХ ===');
  console.log('Количество записей для агрегации:', data.length);
  console.log('Уникальные поля:', Array.from(numericFields));
  console.log('Агрегированные значения:');
  console.log('- Выручка:', aggregated['Выручка'] || 0);
  console.log('- Выручка Сайт:', aggregated['Выручка Сайт'] || 0);
  console.log('- Выручка Оборудование:', aggregated['Выручка Оборудование'] || 0); // ДОБАВИТЬ
  console.log('- Общая выручка (с оборудованием):',
    (aggregated['Выручка'] || 0) +
    (aggregated['Выручка Сайт'] || 0) +
    (aggregated['Выручка Оборудование'] || 0)
  );

  return aggregated;
}

function formatCurrency(value) {
  if (value === 0) return '0';
  const absValue = Math.abs(value);
  if (absValue >= 1000000) {
    return (value / 1000000).toFixed(1) + 'M';
  } else if (absValue >= 1000) {
    return (value / 1000).toFixed(0) + 'k';
  }
  return Math.round(value).toLocaleString('ru-RU', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
}

// НОВАЯ ФУНКЦИЯ: Детализация выручки по всем объектам (4 столбца)
function showAllObjectsRevenueDetails(dateFrom, dateTo) {
  // 1. Вся розница (сумма всех retailObjects)
  const retailRevenue = calculateRetailRevenue(dateFrom, dateTo);

  // 2. Команда маркетинга и продаж франшизы
  const franchiseSalesRevenue = calculateFranchiseSalesRevenue(dateFrom, dateTo);

  // 3. Развитие
  const developmentRevenue = calculateDevelopmentRevenue(dateFrom, dateTo);

  // 4. Команда розницы франшиз
  const franchiseSupportRevenue = calculateFranchiseSupportRevenue(dateFrom, dateTo);

  // Подготавливаем данные для графика
  const revenueData = [
    { category: "Вся розница", revenue: retailRevenue, color: "#4CAF50" },
    { category: "Команда маркетинга и продаж франшизы", revenue: franchiseSalesRevenue, color: "#2196F3" },
    { category: "Развитие", revenue: developmentRevenue, color: "#FF9800" },
    { category: "Команда розницы франшиз", revenue: franchiseSupportRevenue, color: "#9C27B0" }
  ];

  // Создаем график
  createAllObjectsRevenueChart(revenueData, dateFrom, dateTo);
}

// НОВАЯ ФУНКЦИЯ: Расчет выручки для всей розницы
function calculateRetailRevenue(dateFrom, dateTo) {
  let filteredData = allData.filter(row => {
    const object = String(row.Объект || '').trim();
    const address = String(row.Адрес || '').trim();

    // Фильтруем по retailObjects и исключаем франшизу роялти
    return retailObjects.includes(object) &&
      !address.toLowerCase().includes('франшиза роялти');
  });

  // Фильтруем по дате
  if (dateFrom && dateTo) {
    filteredData = filteredData.filter(row => {
      const rowDateStr = row.Дата;
      if (!rowDateStr) return true;
      try {
        const rowDate = new Date(rowDateStr.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        return rowDate >= fromDate && rowDate <= toDate;
      } catch (e) {
        return true;
      }
    });
  }

  // Суммируем выручку
  const totalRevenue = filteredData.reduce((sum, row) => {
    return sum + (row.Выручка || 0) +
      (row['Выручка Сайт'] || 0) +
      (row['Выручка Оборудование'] || 0);  // ДОБАВЛЕНО
  }, 0);

  console.log(`Выручка всей розницы: ${formatCurrency(totalRevenue)} (${filteredData.length} записей)`);
  return totalRevenue;
}

// НОВАЯ ФУНКЦИЯ: Расчет выручки франшизы отдела продаж
function calculateFranchiseSalesRevenue(dateFrom, dateTo) {
  let filteredData = allData.filter(row => {
    const object = String(row.Объект || '').trim();
    const address = String(row.Адрес || '').trim();

    // Ищем франшизу отдела продаж
    return (object === 'Команда маркетинга и продаж франшизы' ||
      address.toLowerCase().includes('Команда маркетинга и продаж франшизы') ||
      address.toLowerCase().includes('Команда маркетинга и продаж франшизы'));
  });

  // Фильтруем по дате
  if (dateFrom && dateTo) {
    filteredData = filteredData.filter(row => {
      const rowDateStr = row.Дата;
      if (!rowDateStr) return true;
      try {
        const rowDate = new Date(rowDateStr.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        return rowDate >= fromDate && rowDate <= toDate;
      } catch (e) {
        return true;
      }
    });
  }

  // Суммируем выручку
  const totalRevenue = filteredData.reduce((sum, row) => {
    return sum + (row.Выручка || 0) +
      (row['Выручка Сайт'] || 0) +
      (row['Выручка Оборудование'] || 0);  // ДОБАВЛЕНО
  }, 0);

  console.log(`Выручка франшизы отдела продаж: ${formatCurrency(totalRevenue)} (${filteredData.length} записей)`);
  return totalRevenue;
}

// НОВАЯ ФУНКЦИЯ: Расчет выручки Развития
function calculateDevelopmentRevenue(dateFrom, dateTo) {
  let filteredData = allData.filter(row => {
    const object = String(row.Объект || '').trim();
    const address = String(row.Адрес || '').trim();

    // Ищем Развитие
    return object === 'Развитие' ||
      address.toLowerCase().includes('развитие');
  });

  // Фильтруем по дате
  if (dateFrom && dateTo) {
    filteredData = filteredData.filter(row => {
      const rowDateStr = row.Дата;
      if (!rowDateStr) return true;
      try {
        const rowDate = new Date(rowDateStr.split('.').reverse().join('-'));
        const fromDate = new Date(dateFrom);
        const toDate = new Date(dateTo);
        return rowDate >= fromDate && rowDate <= toDate;
      } catch (e) {
        return true;
      }
    });
  }

  // Суммируем выручку
  const totalRevenue = filteredData.reduce((sum, row) => {
    return sum + (row.Выручка || 0) +
      (row['Выручка Сайт'] || 0) +
      (row['Выручка Оборудование'] || 0);  // ДОБАВЛЕНО
  }, 0);

  console.log(`Выручка Развития: ${formatCurrency(totalRevenue)} (${filteredData.length} записей)`);
  return totalRevenue;
}

// НОВАЯ ФУНКЦИЯ: Расчет выручки франшизы сопровождения
function calculateFranchiseSupportRevenue(dateFrom, dateTo) {
  if (!dateFrom || !dateTo) return 0;

  const fromDate = new Date(dateFrom);
  const toDate = new Date(dateTo);

  const filteredSupportData = supportData.filter(item => {
    if (!item.Дата) return false;
    try {
      const itemDate = new Date(item.Дата.split('.').reverse().join('-'));
      return itemDate >= fromDate && itemDate <= toDate;
    } catch (e) {
      return false;
    }
  });

  // Суммируем все оплаты от франчайзи
  const totalRevenue = filteredSupportData.reduce((total, item) => {
    return total +
      (item["Оплаты от франчайзи за а/х"] || 0) +
      (item["Оплаты от франчайзи за ворота"] || 0) +
      (item["Оплаты от франчайзи за прочее"] || 0);
  }, 0);

  console.log(`Выручка франшизы сопровождения: ${formatCurrency(totalRevenue)} (${filteredSupportData.length} записей)`);
  return totalRevenue;
}

// НОВАЯ ФУНКЦИЯ: Создание графика выручки по всем объектам
function createAllObjectsRevenueChart(revenueData, dateFrom, dateTo) {
  if (currentChart) {
    currentChart.dispose();
    currentChart = null;
  }

  const chart = echarts.init(document.getElementById('chart'));
  currentChart = chart;

  // Подготавливаем данные для графика
  const categories = revenueData.map(item => item.category);
  const revenues = revenueData.map(item => item.revenue);
  const colors = revenueData.map(item => item.color);

  const option = {
    title: {
      text: 'Выручка по направлениям бизнеса',
      subtext: dateFrom && dateTo ? `Период: ${formatDateForDisplay(dateFrom)} - ${formatDateForDisplay(dateTo)}` : '',
      left: 'center',
      textStyle: {
        fontSize: 16,
        fontWeight: 'bold'
      }
    },
    tooltip: {
      trigger: 'axis',
      axisPointer: {
        type: 'shadow'
      },
      formatter: function (params) {
        const data = params[0];
        const value = data.value;
        const category = data.name;
        const totalRevenue = revenues.reduce((sum, val) => sum + val, 0);
        const percentage = totalRevenue > 0 ? ((value / totalRevenue) * 100).toFixed(1) : 0;

        let description = '';
        if (category === "Вся розница") {
          description = "Включает 8 управляющих: Козубенко Денис, Сенатов Кирилл и др.";
        } else if (category === "Команда маркетинга и продаж франшизы") {
          description = "Выручка от продажи франшиз";
        } else if (category === "Развитие") {
          description = "Доходы от проектов развития";
        } else if (category === "Команда розницы франшиз") {
          description = "Оплаты а/х, ворота, прочее, роялти";
        }

        return `
          <div style="text-align: left; padding: 5px;">
            <strong>${category}</strong><br/>
            ${description}<br/>
            Выручка: ${formatCurrency(value)}<br/>
            Доля от общей: ${percentage}%
          </div>
        `;
      }
    },
    grid: {
      left: '10%',
      right: '10%',
      bottom: '15%',
      top: '15%',
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: categories,
      axisLabel: {
        interval: 0,
        rotate: 0,
        fontSize: 12,
        margin: 10,
        fontWeight: 'bold'
      },
      axisTick: {
        alignWithLabel: true
      }
    },
    yAxis: {
      type: 'value',
      scale: true,
      axisLabel: {
        formatter: formatCurrency
      },
      splitLine: {
        lineStyle: {
          type: 'dashed'
        }
      }
    },
    series: [
      {
        name: 'Выручка',
        type: 'bar',
        barWidth: '50%',
        data: revenues.map((value, index) => ({
          value: value,
          itemStyle: {
            color: colors[index],
            shadowBlur: 10,
            shadowColor: 'rgba(0, 0, 0, 0.3)',
            borderRadius: [5, 5, 0, 0]
          }
        })),
        label: {
          show: true,
          position: 'top',
          formatter: function (params) {
            return formatCurrency(params.value);
          },
          fontSize: 11,
          fontWeight: 'bold',
          color: '#333'
        },
        emphasis: {
          itemStyle: {
            shadowBlur: 20,
            shadowColor: 'rgba(0, 0, 0, 0.5)'
          }
        }
      }
    ]
  };

  chart.setOption(option);

  // Обновляем статистику
  const totalRevenue = revenues.reduce((sum, value) => sum + value, 0);
  const maxRevenue = Math.max(...revenues);
  const minRevenue = Math.min(...revenues);
  const maxCategory = revenueData.find(item => item.revenue === maxRevenue)?.category || 'Н/Д';
  const minCategory = revenueData.find(item => item.revenue === minRevenue)?.category || 'Н/Д';

  document.getElementById('statsInfo').innerHTML = `
    <div class="stat-item" style="background-color: #f8f9fa; border-left: 4px solid #007bff;">
      <strong>Общая выручка по всем направлениям</strong>
    </div>
    <div class="stat-item">Период: ${dateFrom ? formatDateForDisplay(dateFrom) : 'н/д'} - ${dateTo ? formatDateForDisplay(dateTo) : 'н/д'}</div>
    <div class="stat-item" style="background-color: #4CAF5030;">Вся розница: ${formatCurrency(revenueData[0].revenue)}</div>
    <div class="stat-item" style="background-color: #2196F330;">Франшиза продаж: ${formatCurrency(revenueData[1].revenue)}</div>
    <div class="stat-item" style="background-color: #FF980030;">Развитие: ${formatCurrency(revenueData[2].revenue)}</div>
    <div class="stat-item" style="background-color: #9C27B030;">Команда розницы франшиз: ${formatCurrency(revenueData[3].revenue)}</div>
    <div class="stat-item">Общая выручка: ${formatCurrency(totalRevenue)}</div>
    <div class="stat-item">Максимум: ${formatCurrency(maxRevenue)} (${maxCategory})</div>
    <div class="stat-item">Минимум: ${formatCurrency(minRevenue)} (${minCategory})</div>
  `;

  // Добавляем клик по столбцам для детализации
  chart.on('click', function (params) {
    if (params.componentType === 'series' && params.seriesType === 'bar') {
      const category = params.name;

      if (category === "Вся розница") {
        // Переходим в режим детализации розницы
        document.getElementById('objectSelect').value = 'all_retail';
        document.getElementById('addressSelect').value = '';
        applyFilters();

        // Показываем сообщение
        setTimeout(() => {
          alert('Переключено в режим "Вся розница". Кликните на столбец "Выручка" для детализации по адресам.');
        }, 100);
      }
      else if (category === "Команда маркетинга и продаж франшизы") {
        alert('Для франшизы отдела продаж детализация будет доступна в будущих обновлениях.');
      }
      else if (category === "Развитие") {
        alert('Для направления "Развитие" детализация будет доступна в будущих обновлениях.');
      }
      else if (category === "Команда розницы франшиз") {
        // Переходим в режим франшизы сопровождения
        document.getElementById('objectSelect').value = 'Команда розницы франшиз';
        document.getElementById('addressSelect').value = '';
        applyFilters();

        // Показываем сообщение
        setTimeout(() => {
          alert('Переключено в режим "Команда розницы франшиз". Кликните на столбец "Выручка" для детализации оплат.');
        }, 100);
      }
    }
  });

  window.addEventListener('resize', function () {
    chart.resize();
  });
}

// ИСПРАВЛЕННАЯ ФУНКЦИЯ: renderChart() - с визуальным разделением выручки
function renderChart(chart, categories, waterfallData, object, addresses, showCompanyExpenses, totalRevenue, regularRevenue, bonusRevenue) {
  const revenueIndex = categories.indexOf("Выручка");
  const profitIndex = categories.indexOf("Чистая прибыль");

  // Получаем последнее значение из waterfallData (это Чистая прибыль)
  const profit = waterfallData[waterfallData.length - 1].end;
  const revenue = totalRevenue;
  const profitability = revenue !== 0 ? (profit / revenue) * 100 : -100;
  const bonusPercentage = revenue > 0 && bonusRevenue > 0 ? ((bonusRevenue / revenue) * 100).toFixed(1) : 0;

  // Проверяем режим "Все объекты + Все адреса"
  const selectedObject = getSelectedObject();
  const selectedAddresses = getSelectedAddresses();
  const isAllObjectsAllAddresses = (!selectedObject || selectedObject === '') &&
    (!selectedAddresses || selectedAddresses.length === 0);

  let titleText = 'Каскадная диаграмма - Финансовый анализ';
  let subtitle = `Рентабельность: ${profitability.toFixed(1)}%`;

  if (isAllObjectsAllAddresses) {
    subtitle += ` (скорректировано с учетом исходящего НДС и налога на прибыль 25%)`;
  }

  const dateFrom = document.getElementById('dateFrom').value;
  const dateTo = document.getElementById('dateTo').value;
  if (dateFrom && dateTo) {
    subtitle += ` | Период: ${formatDateForDisplay(dateFrom)} - ${formatDateForDisplay(dateTo)}`;
  }
  if (object) {
    subtitle += ` | ${object === 'all_retail' ? 'Вся розница' : object}`;
  }
  if (addresses) {
    subtitle += ` | Адресов: ${addresses.length}`;
  }
  if (bonusRevenue > 0) {
    subtitle += ` | Бонус: ${formatCurrency(bonusRevenue)} (${bonusPercentage}% от выручки)`;
  }

  const seriesData = waterfallData.map((item, index) => {
    const category = categories[index];
    const isPositive = item.value >= 0;
    const isProfit = category === "Чистая прибыль";

    let itemStyle = {};
    const selectedObject = getSelectedObject();
    const selectedAddresses = getSelectedAddresses();
    const isAllObjectsAllAddresses = isAllObjectsAllAddressesMode(selectedObject, selectedAddresses);
    const isAllRetailAllAddresses = (selectedObject === 'all_retail' || selectedObject === '') &&
      (!selectedAddresses || selectedAddresses.length === 0);
    const isFranchiseSupport = selectedObject === 'Команда розницы франшиз';
    const isManagerModeActive = isManagerMode(selectedObject);

    if (category === "Выручка") {
      // Создаем специальный стиль для столбца с разделением
      if (item.showBonus && bonusRevenue > 0) {
        // Используем градиент для разделения
        const bonusRatio = bonusRevenue / item.value;
        const regularRatio = 1 - bonusRatio;

        itemStyle = {
          color: {
            type: 'linear',
            x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [
              { offset: 0, color: '#4CAF50' }, // Обычная выручка (сверху)
              { offset: regularRatio, color: '#4CAF50' },
              { offset: regularRatio, color: '#FFC107' }, // Бонус (снизу)
              { offset: 1, color: '#FFC107' }
            ]
          },
          borderColor: '#fff',
          borderWidth: 2,
          cursor: (isAllObjectsAllAddresses || isAllRetailAllAddresses || isFranchiseSupport || isManagerModeActive) ? 'pointer' : 'default'
        };
      } else {
        itemStyle = {
          color: '#4CAF50',
          borderColor: '#fff',
          borderWidth: 2,
          cursor: (isAllObjectsAllAddresses || isAllRetailAllAddresses || isFranchiseSupport || isManagerModeActive) ? 'pointer' : 'default'
        };
      }
    } else if (isProfit) {
      itemStyle = {
        color: item.value >= 0 ? '#28a745' : '#dc3545',
        borderColor: '#fff',
        borderWidth: 2
      };
    } else if (category === "Прочие" || category === "Общий расход" || category === "З/п офис" || category === "Инвестиционный расход") {
      itemStyle = {
        color: isPositive ? '#4CAF50' : '#F44336',
        borderColor: '#fff',
        borderWidth: 2,
        cursor: 'pointer'
      };
    } else if (category === "Неделимый расход") {
      const isDrilldownMode = (!selectedObject || selectedObject === 'all_retail') &&
        (!selectedAddresses || selectedAddresses.length === 0);
      itemStyle = {
        color: isPositive ? '#4CAF50' : '#F44336',
        borderColor: '#fff',
        borderWidth: 2,
        cursor: isDrilldownMode ? 'pointer' : 'default'
      };
    } else {
      itemStyle = {
        color: isPositive ? '#4CAF50' : '#F44336',
        borderColor: '#fff',
        borderWidth: 2
      };
    }

    return {
      value: item.value,
      itemStyle: itemStyle,
      category: category,
      regularRevenue: item.regularRevenue,
      bonusRevenue: item.bonusRevenue,
      showBonus: item.showBonus
    };
  });

  const option = {
    title: {
      text: titleText,
      subtext: subtitle,
      left: 'center',
      textStyle: {
        fontSize: 16,
        fontWeight: 'bold'
      }
    },
    tooltip: {
      trigger: 'axis',
      axisPointer: {
        type: 'shadow'
      },
      formatter: function (params) {
        const tar = params[0];
        const value = tar.value;
        const category = tar.data.category || categories[tar.dataIndex];

        let tooltip = `
          <div style="text-align: left; min-width: 250px;">
            <strong style="font-size: 14px;">${category}</strong><br/>
        `;

        if (category === "Выручка" && tar.data.showBonus) {
          const regular = tar.data.regularRevenue || 0;
          const bonus = tar.data.bonusRevenue || 0;
          const bonusPct = value > 0 ? ((bonus / value) * 100).toFixed(1) : 0;

          tooltip += `
            <div style="margin-top: 8px;">
              <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
                <span>Основная выручка:</span>
                <strong style="color: #4CAF50;">${formatCurrency(regular)}</strong>
              </div>
              <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
                <span>Франшиза роялти:</span>
                <strong style="color: #FFC107;">${formatCurrency(bonus)}</strong>
              </div>
              <div style="border-top: 1px dashed #ccc; margin: 8px 0; padding-top: 4px; display: flex; justify-content: space-between;">
                <span>Общая выручка:</span>
                <strong>${formatCurrency(value)}</strong>
              </div>
              <div style="display: flex; justify-content: space-between; color: #666;">
                <span>Доля бонуса:</span>
                <span>${bonusPct}%</span>
              </div>
            </div>
          `;
        } else {
          tooltip += `<div style="margin-top: 8px;"><strong>${formatCurrency(value)}</strong></div>`;
        }

        const selectedObject = getSelectedObject();
        const selectedAddresses = getSelectedAddresses();
        const isAllObjectsAllAddresses = isAllObjectsAllAddressesMode(selectedObject, selectedAddresses);
        const isAllRetailAllAddresses = (selectedObject === 'all_retail' || selectedObject === '') &&
          (!selectedAddresses || selectedAddresses.length === 0);
        const isFranchiseSupport = selectedObject === 'Команда розницы франшиз';
        const isManagerModeActive = isManagerMode(selectedObject);

        if (category === "Выручка") {
          if (isAllObjectsAllAddresses) {
            tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для просмотра выручки по 4 направлениям бизнеса</em>`;
          } else if (isAllRetailAllAddresses) {
            tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации выручки по всем адресам розницы</em>`;
          } else if (isFranchiseSupport) {
            tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации оплат от франчайзи</em>`;
          } else if (isManagerModeActive) {
            tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации выручки по адресам управляющего</em>`;
          }
        } else if (category === "Прочие") {
          const filteredExpenses = getFilteredOtherExpenses();
          tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации (${filteredExpenses.length} записей)</em>`;
        } else if (category === "Неделимый расход") {
          const isDrilldownMode = (!selectedObject || selectedObject === 'all_retail') &&
            (!selectedAddresses || selectedAddresses.length === 0);
          if (isDrilldownMode) {
            const filteredExpenses = getFilteredIndivisibleExpenses();
            tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации (${filteredExpenses.length} записей)</em>`;
          }
        } else if (category === "Общий расход") {
          const filteredExpenses = getFilteredGeneralExpenseExpenses();
          tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации (${filteredExpenses.length} записей)</em>`;
        } else if (category === "З/п офис") {
          const filteredExpenses = getFilteredSalaryOfficeExpenses();
          tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации (${filteredExpenses.length} записей)</em>`;
        } else if (category === "Инвестиционный расход") {
          const constructionTotal = getConstructionExpenseForDateRange();
          tooltip += `<br/><em style="color: #666; font-size: 11px;">Кликните для детализации (расходы с 01.04.2026)</em>`;
        }

        tooltip += `</div>`;
        return tooltip;
      }
    },
    legend: {
      show: false
    },
    grid: {
      left: '5%',
      right: '5%',
      bottom: '15%',
      top: '15%',
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: categories,
      axisLabel: {
        interval: 0,
        rotate: 45,
        fontSize: 11,
        margin: 10
      },
      axisTick: {
        alignWithLabel: true
      }
    },
    yAxis: {
      type: 'value',
      scale: true,
      axisLabel: {
        formatter: formatCurrency
      }
    },
    series: [
      {
        name: 'Финансовый поток',
        type: 'bar',
        barWidth: '60%',
        emphasis: {
          itemStyle: {
            shadowBlur: 10,
            shadowColor: 'rgba(0, 0, 0, 0.5)'
          }
        },
        label: {
          show: true,
          position: 'inside',
          formatter: function (params) {
            return formatCurrency(params.value);
          },
          fontSize: 10,
          color: '#fff',
          fontWeight: 'bold'
        },
        data: seriesData
      }
    ]
  };

  chart.setOption(option);

  // Добавляем легенду для пояснения цветов
  if (bonusRevenue > 0) {
    const legendDiv = document.createElement('div');
    legendDiv.style.cssText = `
      display: flex;
      justify-content: center;
      gap: 30px;
      margin-top: 15px;
      padding: 10px;
      background: #f8f9fa;
      border-radius: 8px;
      font-size: 13px;
    `;
    legendDiv.innerHTML = `
      <div style="display: flex; align-items: center;">
        <div style="width: 20px; height: 20px; background: #4CAF50; margin-right: 8px; border-radius: 4px;"></div>
        <span>Основная выручка (${formatCurrency(regularRevenue)})</span>
      </div>
      <div style="display: flex; align-items: center;">
        <div style="width: 20px; height: 20px; background: #FFC107; margin-right: 8px; border-radius: 4px;"></div>
        <span>Франшиза роялти (${formatCurrency(bonusRevenue)} - ${bonusPercentage}%)</span>
      </div>
    `;

    const chartContainer = document.getElementById('chart');
    const existingLegend = document.getElementById('bonusLegend');
    if (existingLegend) {
      existingLegend.remove();
    }
    legendDiv.id = 'bonusLegend';
    chartContainer.parentNode.insertBefore(legendDiv, chartContainer.nextSibling);
  }

  chart.on('click', function (params) {
    if (params.componentType === 'series' && params.seriesType === 'bar') {
      const category = params.data.category || categories[params.dataIndex];
      const selectedObject = getSelectedObject();
      const selectedAddresses = getSelectedAddresses();
      const isAllObjectsAllAddresses = isAllObjectsAllAddressesMode(selectedObject, selectedAddresses);
      const isAllRetailAllAddresses = (selectedObject === 'all_retail' || selectedObject === '') &&
        (!selectedAddresses || selectedAddresses.length === 0);
      const isFranchiseSupport = selectedObject === 'Команда розницы франшиз';
      const isManagerModeActive = isManagerMode(selectedObject);

      if (category === "Выручка") {
        if (isAllObjectsAllAddresses || isAllRetailAllAddresses || isFranchiseSupport || isManagerModeActive) {
          showRevenueDetailsByAddress();
        } else {
          alert('Детализация выручки доступна только в режиме "Все объекты + Все адреса", "Вся розница + Все адреса", "Команда розницы франшиз" или для отдельного управляющего');
        }
      } else if (category === "Прочие") {
        showExpensesDetails();
      } else if (category === "Неделимый расход") {
        const isDrilldownMode = (!selectedObject || selectedObject === 'all_retail') &&
          (!selectedAddresses || selectedAddresses.length === 0);
        if (isDrilldownMode) {
          showIndivisibleDetails();
        } else {
          alert('Детализация "Неделимый расход" доступна только в режиме дриллдауна (Все объекты/Вся розница + Все адреса)');
        }
      } else if (category === "Общий расход") {
        showGeneralExpenseDetails();
      } else if (category === "З/п офис") {
        showSalaryOfficeDetails();
      } else if (category === "Инвестиционный расход") {
        showConstructionDetails();
      }
    }
  });

  updateStats(totalRevenue, bonusRevenue, profit, profitability);

  window.addEventListener('resize', function () {
    chart.resize();
  });
}

// ОБНОВЛЕННАЯ ФУНКЦИЯ updateStats() - корректное сравнение
function updateStats(totalRevenue, bonusRevenue, profit, profitability) {
    const selectedObject = getSelectedObject();
    const isManagerModeActive = isManagerMode(selectedObject);
    const regularRevenue = totalRevenue - bonusRevenue;
    const bonusPercentage = totalRevenue > 0 ? ((bonusRevenue / totalRevenue) * 100).toFixed(1) : 0;
    
    const selectedAddresses = getSelectedAddresses();
    const isAllObjectsAllAddresses = (!selectedObject || selectedObject === '') &&
        (!selectedAddresses || selectedAddresses.length === 0);
    
    // Получаем агрегированные данные текущего периода
    let currentAggregated = {};
    let prevPeriodData = null;
    
    if (comparisonMode) {
        const dateFrom = document.getElementById('dateFrom').value;
        const dateTo = document.getElementById('dateTo').value;
        if (dateFrom && dateTo) {
            // Получаем отфильтрованные данные для текущего периода
            let filteredData = allData.filter(row => {
                const address = String(row.Адрес || '').trim();
                return !address.toLowerCase().includes('франшиза роялти');
            });
            
            const fromDate = new Date(dateFrom);
            const toDate = new Date(dateTo);
            
            filteredData = filteredData.filter(row => {
                let rowDate = null;
                if (row.Дата) {
                    try {
                        rowDate = new Date(row.Дата.split('.').reverse().join('-'));
                    } catch (e) {
                        return false;
                    }
                }
                return rowDate && rowDate >= fromDate && rowDate <= toDate;
            });
            
            if (selectedObject) {
                if (selectedObject === 'all_retail') {
                    filteredData = filteredData.filter(row => retailObjects.includes(row.Объект));
                } else if (selectedObject) {
                    filteredData = filteredData.filter(row => row.Объект === selectedObject);
                }
            }
            
            if (selectedAddresses && selectedAddresses.length > 0) {
                const validAddresses = selectedAddresses.filter(addr => addr && addr !== '');
                if (validAddresses.length > 0) {
                    filteredData = filteredData.filter(row => {
                        const rowAddress = String(row.Адрес || '').trim();
                        if (!rowAddress) return false;
                        const rowStandardizedAddress = standardizeAddress(rowAddress);
                        for (const selectedAddr of validAddresses) {
                            const selectedStandardizedAddr = standardizeAddress(selectedAddr);
                            if (rowAddress === selectedAddr) return true;
                            if (rowStandardizedAddress === selectedStandardizedAddr) return true;
                            if (rowAddress.toLowerCase() === selectedAddr.toLowerCase()) return true;
                            if (rowAddress.includes(selectedAddr) || selectedAddr.includes(rowAddress)) return true;
                        }
                        return false;
                    });
                }
            }
            
            currentAggregated = aggregateCategories(filteredData);
            prevPeriodData = getPreviousPeriodData(dateFrom, dateTo, selectedObject, selectedAddresses);
        }
    }
    
    let statsHtml = '';
    
    if (comparisonMode && prevPeriodData) {
        const prevTotalRevenue = prevPeriodData.totalRevenue || 0;
        const prevProfit = prevPeriodData.profit || 0;
        const prevBonusRevenue = prevPeriodData.bonusRevenue || 0;
        const prevRegularRevenue = prevPeriodData.regularRevenue || 0;
        const prevProfitability = prevTotalRevenue !== 0 ? (prevProfit / prevTotalRevenue) * 100 : 0;
        
        const revenueChange = calculateChange(totalRevenue, prevTotalRevenue);
        const revenueChangeAbs = totalRevenue - prevTotalRevenue;
        const profitChange = calculateChange(profit, prevProfit);
        const profitChangeAbs = profit - prevProfit;
        const profitabilityChange = profitability - prevProfitability;
        
        statsHtml = `
            <div class="stat-item" style="background: #e8f5e9; border-left: 4px solid #2e7d32;">
                <strong>💰 Выручка: ${formatCurrency(totalRevenue)}</strong>
                <div style="font-size: 11px; margin-top: 4px; color: #555;">
                    📊 ${prevPeriodData.periodLabel}: ${formatCurrency(prevTotalRevenue)}
                </div>
                <div style="margin-top: 6px;">
                    ${revenueChange >= 0 ? '▲' : '▼'} 
                    <span class="${revenueChange >= 0 ? 'change-positive' : 'change-negative'}" style="color: ${revenueChange >= 0 ? '#4CAF50' : '#F44336'}; font-weight: bold;">
                        ${Math.abs(revenueChange).toFixed(1)}% (${formatCurrency(Math.abs(revenueChangeAbs))})
                    </span>
                </div>
            </div>
        `;
        
        // Основная выручка и бонус
        statsHtml += `
            <div class="stat-item" style="display: flex; justify-content: space-between; background: #fff3e0; border-left-color: #f57c00;">
                <span>📋 Основная выручка:</span>
                <span style="color: #2e7d32; font-weight: bold;">${formatCurrency(regularRevenue)}</span>
                <span style="font-size: 10px; color: #888;">${formatCurrency(prevRegularRevenue)}</span>
            </div>
            <div class="stat-item" style="display: flex; justify-content: space-between; background: #fff3e0; border-left-color: #f57c00;">
                <span>⭐ Франшиза роялти:</span>
                <span style="color: #f57c00; font-weight: bold;">${formatCurrency(bonusRevenue)} (${bonusPercentage}%)</span>
                <span style="font-size: 10px; color: #888;">${formatCurrency(prevBonusRevenue)}</span>
            </div>
        `;
        
        // Прибыль
        statsHtml += `
            <div class="stat-item ${profit >= 0 ? 'positive' : 'negative'}" style="border-left: 4px solid ${profit >= 0 ? '#4CAF50' : '#F44336'};">
                <strong>📈 Прибыль: ${formatCurrency(profit)}</strong>
                <div style="font-size: 11px; margin-top: 2px; color: #666;">
                    ${prevPeriodData.periodLabel}: ${formatCurrency(prevProfit)}
                </div>
                <div style="margin-top: 6px;">
                    ${profitChange >= 0 ? '▲' : '▼'} 
                    <span class="${profitChange >= 0 ? 'change-positive' : 'change-negative'}" style="color: ${profitChange >= 0 ? '#4CAF50' : '#F44336'}; font-weight: bold;">
                        ${Math.abs(profitChange).toFixed(1)}% (${formatCurrency(Math.abs(profitChangeAbs))})
                    </span>
                </div>
            </div>
        `;

        // Рентабельность
        statsHtml += `
            <div class="stat-item ${profitability >= 0 ? 'positive' : 'negative'}" style="border-left: 4px solid ${profitability >= 0 ? '#4CAF50' : '#F44336'};">
                <strong>📊 Рентабельность: ${profitability.toFixed(1)}%</strong>
                <div style="font-size: 11px; margin-top: 2px; color: #666;">
                    ${prevPeriodData.periodLabel}: ${prevProfitability.toFixed(1)}%
                </div>
                <div style="margin-top: 6px;">
                    ${profitabilityChange >= 0 ? '▲' : '▼'} 
                    <span class="${profitabilityChange >= 0 ? 'change-positive' : 'change-negative'}" style="color: ${profitabilityChange >= 0 ? '#4CAF50' : '#F44336'}; font-weight: bold;">
                        ${Math.abs(profitabilityChange).toFixed(1)} п.п.
                    </span>
                </div>
            </div>
        `;
        
        // ========== ТАБЛИЦА РАСХОДОВ (УЛУЧШЕННАЯ ВЕРСИЯ) ==========
        statsHtml += `
            <div class="stat-item" style="background: #f5f5f5; margin-top: 12px; padding: 0; overflow: hidden; border-radius: 8px;">
                <div style="background: #1565c0; color: white; padding: 8px 12px; font-weight: bold; font-size: 13px;">
                    📉 Сравнение расходов
                </div>
                <div style="padding: 8px;">
                    <table style="width: 100%; font-size: 11px; border-collapse: collapse;">
                        <thead>                    <tr style="background: #e3e3e3;">
                                <th style="padding: 6px 4px; text-align: left;">Статья</th>
                                <th style="padding: 6px 4px; text-align: right;">Текущий</th>
                                <th style="padding: 6px 4px; text-align: right;">Предыдущий</th>
                                <th style="padding: 6px 4px; text-align: right;">Изменение</th>
                                <th style="padding: 6px 4px; text-align: center;">Тренд</th>
                            </tr>
                        </thead>
                        <tbody>
        `;
        
        // Функция получения значений для категорий
        const getCategoryValue = (catName, isCurrent) => {
            const data = isCurrent ? currentAggregated : prevPeriodData.aggregated;
            switch(catName) {
                case "Автохимия":
                    return Math.abs((data['Автохимия Шампунь Москва'] || 0) + 
                                   (data['Автохимия Шампунь СПБ'] || 0) +
                                   (data['Автохимия Пена'] || 0) + 
                                   (data['Автохимия Юр. Лица'] || 0) +
                                   (data['Автохимия Абонементы/сертификаты/подписки'] || 0));
                case "Коммунальные":
                    return Math.abs((data['Коммунальные расходы'] || 0) +
                                   (data['Коммунальные расходы Абонементы/сертификаты/подписки'] || 0));
                case "Аренда":
                    return Math.abs(data['Аренда'] || 0);
                case "Зарплата":
                    return Math.abs(data['Зарплата'] || 0);
                case "Комиссии":
                    return Math.abs(data['Комиссии'] || 0);
                case "Налоги":
                    if (isCurrent) {
                        return currentAggregated['Налоги'] || 0;  // Сохраняем знак
                    } else {
                        return prevPeriodData.aggregated['Налоги'] || 0;
                    }
                case "НДС":
                    if (isCurrent) {
                        return currentAggregated['НДС'] || 0;  // Сохраняем знак
                    } else {
                        return prevPeriodData.aggregated['НДС'] || 0;
                    }
                case "НДС":
                    return Math.abs(data['НДС'] || 0);
                case "Прочие":
                    if (isCurrent) {
                        const otherExpenses = getFilteredOtherExpenses();
                        return Math.abs(otherExpenses.reduce((sum, item) => sum + item.сумма, 0));
                    } else {
                        return Math.abs(data['Прочие'] || 0);
                    }
                case "Неделимый":
                    if (isCurrent) {
                        return Math.abs(getIndivisibleExpenseForDateRange(selectedObject, selectedAddresses));
                    } else {
                        return Math.abs(data['Неделимый расход'] || 0);
                    }
                case "Общий расход":
                    if (isCurrent) {
                        return Math.abs(getAdjustedGeneralExpenseForDateRange());
                    } else {
                        return Math.abs(data['Общий расход'] || 0);
                    }
                case "З/п офис":
                    if (isCurrent) {
                        return Math.abs(calculateSalaryForPeriod());
                    } else {
                        return Math.abs(data['З/п офис'] || 0);
                    }
                default:
                    return 0;
            }
        };
        
        const expenseTableCategories = [
            { name: "Автохимия", isExpense: true },
            { name: "Коммунальные", isExpense: true },
            { name: "Аренда", isExpense: true },
            { name: "Зарплата", isExpense: true },
            { name: "Комиссии", isExpense: true },
            { name: "Налоги", isExpense: false },  // Налоги могут быть как +, так и -
            { name: "НДС", isExpense: false },     // НДС может быть как +, так и -
            { name: "Прочие", isExpense: true },
            { name: "Неделимый", isExpense: true }
        ];

        // Добавляем общие расходы, З/п офис и Инвестиционный расход только в режиме "Все объекты"
        if (isAllObjectsAllAddresses) {
            expenseTableCategories.push({ name: "Общий расход", isExpense: true });
            expenseTableCategories.push({ name: "З/п офис", isExpense: true });
            expenseTableCategories.push({ name: "Инвестиционный расход", isExpense: true });  // ДОБАВЛЕНО
        }
        
        for (const cat of expenseTableCategories) {
            const currentVal = getCategoryValue(cat.name, true);
            const prevVal = getCategoryValue(cat.name, false);
            
            if (currentVal !== 0 || prevVal !== 0) {
                const changeAbs = currentVal - prevVal;
                const changePercent = prevVal !== 0 ? (changeAbs / prevVal) * 100 : (currentVal !== 0 ? 100 : 0);
                
                // Для расходов: уменьшение = хорошо (зеленый ▲), увеличение = плохо (красный ▼)
                const isImprovement = changeAbs <= 0;
                const arrow = changeAbs > 0 ? '▼' : (changeAbs < 0 ? '▲' : '•');
                const trendColor = isImprovement ? '#4CAF50' : '#F44336';
                const changeFormatted = changePercent !== 0 ? `${arrow} ${Math.abs(changePercent).toFixed(1)}%` : '• 0%';
                
                // Определяем фон строки (чередование)
                const bgColor = expenseTableCategories.indexOf(cat) % 2 === 0 ? '#fafafa' : '#ffffff';
                
                statsHtml += `
                    <tr style="background: ${bgColor}; border-bottom: 1px solid #eee;">
                        <td style="padding: 5px 4px; text-align: left; font-weight: 500;">${cat.name}</td>
                        <td style="padding: 5px 4px; text-align: right; color: #d32f2f;">${formatCurrency(currentVal)}</td>
                        <td style="padding: 5px 4px; text-align: right; color: #d32f2f;">${formatCurrency(prevVal)}</td>
                        <td style="padding: 5px 4px; text-align: right; font-weight: bold; color: ${trendColor};">
                            ${changeFormatted}
                        </td>
                        <td style="padding: 5px 4px; text-align: center;">
                            <span style="color: ${trendColor}; font-size: 14px;">${changeAbs > 0 ? '📈' : (changeAbs < 0 ? '📉' : '➡️')}</span>
                        </td>
                    </tr>
                `;
            }
        }
        
        // ИТОГО расходов
        let totalCurrentExpenses = 0;
        let totalPrevExpenses = 0;
        
        for (const cat of expenseTableCategories) {
            totalCurrentExpenses += getCategoryValue(cat.name, true);
            totalPrevExpenses += getCategoryValue(cat.name, false);
        }
        
        const totalChangeAbs = totalCurrentExpenses - totalPrevExpenses;
        const totalChangePercent = totalPrevExpenses !== 0 ? (totalChangeAbs / totalPrevExpenses) * 100 : 0;
        const totalIsImprovement = totalChangeAbs <= 0;
        const totalArrow = totalChangeAbs > 0 ? '▼' : (totalChangeAbs < 0 ? '▲' : '•');
        const totalTrendColor = totalIsImprovement ? '#4CAF50' : '#F44336';
        
        statsHtml += `
                        <tr style="background: #e8e8e8; border-top: 2px solid #ccc; font-weight: bold;">
                            <td style="padding: 6px 4px; text-align: left;">💰 ИТОГО расходы</td>
                            <td style="padding: 6px 4px; text-align: right; color: #d32f2f;">${formatCurrency(totalCurrentExpenses)}</td>
                            <td style="padding: 6px 4px; text-align: right; color: #d32f2f;">${formatCurrency(totalPrevExpenses)}</td>
                            <td style="padding: 6px 4px; text-align: right; color: ${totalTrendColor};">
                                ${totalArrow} ${Math.abs(totalChangePercent).toFixed(1)}%
                            </td>
                            <td style="padding: 6px 4px; text-align: center;">
                                <span style="color: ${totalTrendColor};">${totalChangeAbs > 0 ? '📈' : (totalChangeAbs < 0 ? '📉' : '➡️')}</span>
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
        `;
        
    } else {
        // ========== ОБЫЧНАЯ СТАТИСТИКА (БЕЗ СРАВНЕНИЯ) ==========
        statsHtml = `
            <div class="stat-item revenue" style="background: #e8f5e9; border-left: 4px solid #2e7d32;">
                <strong>💰 Выручка: ${formatCurrency(totalRevenue)}</strong>
            </div>
        `;
        
        if (bonusRevenue > 0) {
            statsHtml += `
                <div class="stat-item" style="display: flex; justify-content: space-between; background: #fff3e0; border-left-color: #f57c00;">
                    <span>📋 Основная выручка:</span>
                    <span style="color: #2e7d32; font-weight: bold;">${formatCurrency(regularRevenue)}</span>
                </div>
                <div class="stat-item" style="display: flex; justify-content: space-between; background: #fff3e0; border-left-color: #f57c00;">
                    <span>⭐ Франшиза роялти:</span>
                    <span style="color: #f57c00; font-weight: bold;">${formatCurrency(bonusRevenue)} (${bonusPercentage}%)</span>
                </div>
            `;
        }
        
        statsHtml += `
            <div class="stat-item ${profit >= 0 ? 'positive' : 'negative'}" style="border-left: 4px solid ${profit >= 0 ? '#4CAF50' : '#F44336'};">
                <strong>📈 Прибыль: ${formatCurrency(profit)}</strong>
            </div>
            <div class="stat-item ${profitability >= 0 ? 'positive' : 'negative'}" style="border-left: 4px solid ${profitability >= 0 ? '#4CAF50' : '#F44336'};">
                <strong>📊 Рентабельность: ${profitability.toFixed(1)}%</strong>
            </div>
        `;
    }
    
    // Дополнительная информация о режиме
    if (isAllObjectsAllAddresses) {
        statsHtml += `
            <div class="stat-item" style="background: #e3f2fd; border-left-color: #1565c0; font-size: 11px;">
                <strong>☑️ Расчет с учетом:</strong><br>
                • Исходящий НДС вычтен из расходов<br>
                • Налог на прибыль 25% учтен
            </div>
        `;
    }
    
    if (isManagerModeActive) {
        statsHtml += `
            <div class="stat-item" style="background: ${getManagerColor(selectedObject)}30; border-left-color: ${getManagerColor(selectedObject)}; font-size: 11px;">
                <strong>👤 Режим управляющего:</strong> ${selectedObject}
            </div>
        `;
    }
    
    document.getElementById('statsInfo').innerHTML = statsHtml;
}

